import { CursorFeature, SafeEventsAdapter, UnSubManager } from "@kvisaz/phaser-common";
import { cursorConfig } from "../configs/config.cursors";
import { soundConfig, soundSettings } from "../configs/config.sound";
import { SCENES } from "../scenes";
import { services } from "../services";
import { GameAdsService } from "../services/ads/GameAdsService";
import { GameSoundService } from "../services/sound/GameSoundService";

/** Сервисы работают до перезагрузки страницы и не перезапускаются вместе с экранами. */
export class ServicesScene extends Phaser.Scene {
  private readonly unSubs = new UnSubManager();

  /** Регистрирует постоянную сцену под общим ключом. */
  constructor() {
    super(SCENES.services);
  }

  /** Подключает постоянных обработчиков до запуска игрового экрана. */
  create(): void {
    const scene = this;
    const { adsService, gameEvents, playerDataService } = services;

    /** Рекламные запросы обслуживаются независимо от текущего экрана. */
    this.unSubs.addUnSub(new GameAdsService({ scene, events: gameEvents, ads: adsService }));

    /** Звук: настройки (сохраняются между запусками), музыка, реакции на игровые события и временный mute. */
    this.unSubs.addUnSub(
      new GameSoundService({
        scene,
        events: gameEvents,
        playerData: playerDataService,
        settings: soundSettings,
        config: soundConfig,
      }),
    );

    /** Курсор работает на протяжении всей игры; игра меняет его событием setCursor. */
    const cursor = new CursorFeature({ scene, config: cursorConfig });
    const cursorEvents = new SafeEventsAdapter<{ setCursor: { type: string } }>(gameEvents);
    this.unSubs.addUnSub(() => cursorEvents.unSubscribeAll());
    this.unSubs.addUnSub(cursorEvents.on("setCursor", ({ type }) => cursor.setType(type)));
    this.unSubs.addUnSub(cursor);
  }

  /** Явная очистка постоянных обработчиков. В обычной игре сцена не выключается. */
  destroy(): void {
    this.unSubs.destroy();
  }
}
