import { SaveResult, SaveService } from "@kvisaz/phaser-common";
import { fromPlayerData, sanitizeSave, toPlayerData } from "./mappers";
import type { INext2048Save, IPlayerData } from "./types";

/**
 * Данные игрока в обычном виде и их запись в хранилище. Игра читает getData(), меняет только через patch()
 * и записывает через flush(); в компактный формат данные переводятся при записи, из него — при init().
 * Один экземпляр на запуск приложения. Это не состояние компонентов (gameState) и не партия:
 * здесь только то, что переживает перезапуск, — пока настройки звука.
 */
export class PlayerDataService {
  private readonly playerData = getDefaultPlayerData();
  private saveApi?: SaveService;
  private timer?: ReturnType<typeof setTimeout>;
  /** номер последней записи: повтор после отказа назначает только она */
  private version = 0;

  /** Вызывается один раз при подготовке в BootScene, до изменения и записи данных игрока. */
  init(saveService: SaveService): void {
    this.saveApi = saveService;
    Object.assign(this.playerData, toPlayerData(sanitizeSave(saveService.get<INext2048Save>())));
  }

  /** Текущие данные игрока без копии: только читать, менять через patch. */
  getData(): IPlayerData {
    return this.playerData;
  }

  /** Меняет данные в памяти: change получает актуальное состояние и возвращает изменённые поля. Запись — flush. */
  patch(change: (prev: IPlayerData) => Partial<IPlayerData>): this {
    Object.assign(this.playerData, change(this.playerData));
    return this;
  }

  /** Записывает свежий компактный снимок; при отказе оставляет одну отложенную попытку. */
  flush(): Promise<SaveResult> {
    clearTimeout(this.timer);
    return this.send(fromPlayerData(this.playerData), ++this.version);
  }

  /** Повтор назначается, только если после этой записи не было более новой. */
  private async send(save: INext2048Save, version: number): Promise<SaveResult> {
    if (this.saveApi == null) return {};
    const result = await this.saveApi
      .save(save)
      .catch((error: unknown): SaveResult => ({ errorMessage: String(error) }));
    if (version === this.version && result.errorMessage) {
      this.timer = setTimeout(
        () => {
          void this.flush();
        },
        Math.max(1000, result.timeToNextSave ?? 5000),
      );
    }
    return result;
  }
}

/** Создаёт отдельный набор начальных данных игрока до загрузки сохранения. */
function getDefaultPlayerData(): IPlayerData {
  return toPlayerData({});
}
