import { openCommonModalInScene, type ICommonModalSceneHandle } from "@kvisaz/phaser-common";
import { connectUiSounds } from "../connectUiSounds";
import { nextUiConfig } from "../config";
import { NextDialogView } from "../NextDialogView/NextDialogView";
import type { INextDialogSpec } from "./types";

interface IOpenNextDialogProps {
  /** сцена, поверх которой показан диалог: она встаёт на паузу, пока диалог открыт */
  parentScene: Phaser.Scene;
  spec: INextDialogSpec;
}

/**
 * Открывает диалог поверх сцены и возвращает id выбранной кнопки; undefined — диалог закрыли без выбора.
 * Ответ отдаётся ПОСЛЕ закрытия и возобновления родительской сцены: действие игрока не должно
 * выполняться, пока сцена ещё на паузе (tween-ы и таймеры замёрзли).
 * Диалог живёт в своей modal-сцене, поэтому звук кнопок подключается к ней отдельно (connectUiSounds).
 * Первый выбор закрывает диалог; повторные нажатия, пока он закрывается, игнорируются.
 */
export function openNextDialog(props: IOpenNextDialogProps): Promise<string | undefined> {
  const { parentScene, spec } = props;
  const { overlayColor, overlayAlpha, dialogAnimationMs } = nextUiConfig;

  return new Promise((resolve) => {
    /** Выбранная кнопка: пока пусто, диалог ждёт игрока */
    let answer: string | undefined;

    const dialog: ICommonModalSceneHandle = openCommonModalInScene({
      parentScene,
      createContent: (scene) => {
        connectUiSounds(scene);

        return new NextDialogView({
          scene,
          accent: spec.accent,
          title: spec.title,
          message: spec.message,
          tileValue: spec.tileValue,
          toggles: spec.toggles,
          actions: spec.actions.map(({ id, label, tone }) => ({
            label,
            tone,
            onClick: () => {
              if (answer !== undefined) return;
              answer = id;
              dialog.close();
            },
          })),
        });
      },
      props: {
        animationDuration: dialogAnimationMs,
        overlayAlpha,
        overlayColor,
        isCloseOnOverlayClick: false,
        /** modal-сцена закрылась, родитель вот-вот возобновится: ответ — на его следующем тике */
        onClose: () => parentScene.time.delayedCall(0, () => resolve(answer)),
      },
    });

    /** Родитель выключился раньше, чем диалог закрылся: его таймеры не сработают, отвечаем сразу */
    parentScene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => resolve(answer));
  });
}
