import { next2048Config } from "../../config";
import { blobPath, strokeSoft, toRgba } from "../../../../common/canvas/canvas";

/** Прозрачная кайма текстур UI, px: рисованный край и обводка не режутся. */
const uiPad = 6;

export type ButtonIcon = "restart" | "undo" | "menu";

/** Сторона текстуры кнопки = размер её Mesh. */
export const buttonTextureSize = next2048Config.buttonSize + uiPad * 2;

/** Размер текстуры капсулы счёта = размер её Mesh. */
export const pillTextureWidth = next2048Config.pillWidth + uiPad * 2;
export const pillTextureHeight = next2048Config.pillHeight + uiPad * 2;

/** Круглая кнопка макета: неровный круг, рисованная обводка, линейная иконка. */
export function drawButtonTexture(ctx: CanvasRenderingContext2D, icon: ButtonIcon) {
  const { buttonSize, buttonOutline, buttonColors, textColor } = next2048Config;
  const center = buttonTextureSize / 2;
  const radius = buttonSize / 2;

  blobPath(ctx, center, center, radius, radius, 2, 0.012, icon.length);
  ctx.fillStyle = toRgba(buttonColors[icon]);
  ctx.fill();
  strokeSoft(ctx, buttonOutline, 2.8);

  ctx.lineWidth = buttonSize * 0.062;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = textColor;
  drawIcon(ctx, icon, center, buttonSize);
}

/** Капсула счёта без числа: число — отдельный текст поверх. seed делает неровность у каждой капсулы своей. */
export function drawPillTexture(
  ctx: CanvasRenderingContext2D,
  colors: { body: number; outline: number },
  seed: number,
) {
  const { pillWidth, pillHeight } = next2048Config;
  const width = pillTextureWidth;
  const height = pillTextureHeight;

  blobPath(ctx, width / 2, height / 2, pillWidth / 2, pillHeight / 2, 4, 0.025, seed);
  ctx.fillStyle = toRgba(colors.body);
  ctx.fill();
  strokeSoft(ctx, colors.outline, 2.4);
}

/** Иконки макета: толстые линии с круглыми концами, размеры — доли диаметра кнопки. */
function drawIcon(ctx: CanvasRenderingContext2D, icon: ButtonIcon, c: number, d: number) {
  ctx.beginPath();

  switch (icon) {
    case "restart": {
      /** Дуга по часовой от правого края почти до верха, стрелка вправо у верхнего конца */
      const r = d * 0.2;
      const from = Phaser.Math.DegToRad(-15);
      const to = Phaser.Math.DegToRad(262);
      ctx.arc(c, c + d * 0.02, r, from, to, false);
      const tipX = c + r * Math.cos(to) + d * 0.04;
      const tipY = c + d * 0.02 + r * Math.sin(to);
      ctx.moveTo(tipX - d * 0.08, tipY - d * 0.075);
      ctx.lineTo(tipX, tipY);
      ctx.lineTo(tipX - d * 0.08, tipY + d * 0.075);
      break;
    }
    case "undo": {
      /** Стрелка влево сверху, петля вниз справа, хвост влево снизу */
      const top = c - d * 0.1;
      const bottom = c + d * 0.15;
      const left = c - d * 0.17;
      const loopX = c + d * 0.05;
      const r = (bottom - top) / 2;
      ctx.moveTo(left, top);
      ctx.lineTo(loopX, top);
      ctx.arc(loopX, top + r, r, -Math.PI / 2, Math.PI / 2, false);
      ctx.lineTo(c - d * 0.09, bottom);
      ctx.moveTo(left + d * 0.075, top - d * 0.075);
      ctx.lineTo(left, top);
      ctx.lineTo(left + d * 0.075, top + d * 0.075);
      break;
    }
    case "menu": {
      for (const dy of [-0.11, 0, 0.11]) {
        ctx.moveTo(c - d * 0.17, c + d * dy);
        ctx.lineTo(c + d * 0.17, c + d * dy);
      }
      break;
    }
  }

  ctx.stroke();
}
