import { next2048Config } from "../../config";
import type { BoardDirection } from "./types";

interface IAddBoardInputProps {
  scene: Phaser.Scene;
  onMove: (direction: BoardDirection) => void;
}

/** Стрелки, WASD и свайп по сцене → направление хода. Возвращает отписку. */
export function addBoardInput({ scene, onMove }: IAddBoardInputProps): () => void {
  const keys: Record<string, BoardDirection> = {
    ArrowUp: "up",
    ArrowDown: "down",
    ArrowLeft: "left",
    ArrowRight: "right",
    w: "up",
    s: "down",
    a: "left",
    d: "right",
  };
  const onKeyDown = (event: KeyboardEvent) => {
    const direction = keys[event.key];
    if (direction) onMove(direction);
  };

  /** Свайп считаем по отпусканию: направление — по большей оси смещения */
  const onPointerUp = (pointer: Phaser.Input.Pointer) => {
    const dx = pointer.upX - pointer.downX;
    const dy = pointer.upY - pointer.downY;
    if (Math.max(Math.abs(dx), Math.abs(dy)) < next2048Config.swipeMinPx) return;

    if (Math.abs(dx) > Math.abs(dy)) onMove(dx > 0 ? "right" : "left");
    else onMove(dy > 0 ? "down" : "up");
  };

  scene.input.keyboard?.on(Phaser.Input.Keyboard.Events.ANY_KEY_DOWN, onKeyDown);
  scene.input.on(Phaser.Input.Events.POINTER_UP, onPointerUp);

  return () => {
    scene.input.keyboard?.off(Phaser.Input.Keyboard.Events.ANY_KEY_DOWN, onKeyDown);
    scene.input.off(Phaser.Input.Events.POINTER_UP, onPointerUp);
  };
}
