import { makeAlign, makeView } from "@kvisaz/phaser-common";
import { JellyLoops, JellyMesh } from "../../../../common/animation/animation-jelly";
import {
  Next2048Textures,
  type ButtonIcon,
} from "../../../Next2048Scene/shared/Next2048Textures/Next2048Textures";
import { addJellyButtonBehavior } from "../../jelly-button/addJellyButtonBehavior";
import { nextUiConfig, type NextUiTone } from "../config";
import { NextUiTextures } from "../NextUiTextures";
import { nextUiMotion } from "../nextUiMotion";

interface INextUiRoundButtonProps {
  scene: Phaser.Scene;
  look: "round";
  /** иконка круглой кнопки: её текстура рисуется в Next2048Textures */
  icon: ButtonIcon;
  /** действие: срабатывает на отпускание над кнопкой */
  onClick: () => void;
}

interface INextUiTileButtonProps {
  scene: Phaser.Scene;
  look: "tile";
  tone: NextUiTone;
  /** подпись: готовая строка */
  label: string;
  /** действие: срабатывает на отпускание над кнопкой */
  onClick: () => void;
}

/** Вид кнопки задаёт look: у круглой — иконка, у плитки — тон и подпись. */
type NextUiButtonProps = INextUiRoundButtonProps | INextUiTileButtonProps;

/**
 * Желейная кнопка интерфейса: круглая с иконкой или плитка с подписью.
 * Желейное поведение — общее с JellyButton (addJellyButtonBehavior); здесь — текстура, подпись и клик на отпускание.
 * Звук клика и наведения шлёт makeButton: нужен мост connectUiSounds(scene) в сцене кнопки.
 */
export class NextUiButton extends Phaser.GameObjects.Container {
  /** подпись есть только у плитки */
  private readonly labelText?: Phaser.GameObjects.Text;
  /** Меняющееся состояние: высота подписи в покое, от неё она уходит вниз при нажатии */
  private readonly gameState = { labelRestY: 0 };

  constructor(private props: NextUiButtonProps) {
    super(props.scene, 0, 0);
    const { scene, onClick } = props;
    const {
      buttonSize,
      fontFamily,
      textColor,
      tileButtonWidth,
      tileButtonHeight,
      labelFontSize,
      disabledAlpha,
    } = nextUiConfig;

    const isRound = props.look === "round";
    const bodyWidth = isRound ? buttonSize : tileButtonWidth;
    const bodyHeight = isRound ? buttonSize : tileButtonHeight;
    const texture =
      props.look === "round"
        ? {
            key: Next2048Textures.button(props.icon),
            width: Next2048Textures.buttonSize,
            height: Next2048Textures.buttonSize,
          }
        : NextUiTextures.tileButton(scene, {
            tone: props.tone,
            width: bodyWidth,
            height: bodyHeight,
          });

    /** Зона задаёт размер и область нажатия: у Mesh нет getBounds */
    const zone = new Phaser.GameObjects.Zone(scene, 0, 0, bodyWidth, bodyHeight);
    this.add(zone);

    const jelly = new JellyMesh({
      scene,
      x: 0,
      y: 0,
      textureKey: texture.key,
      width: texture.width,
      height: texture.height,
    });
    this.add(jelly);
    /** Круглая — рябь по умолчанию; широкая плитка колышется спокойнее, как капсула счёта */
    (isRound ? JellyLoops.loopEdgeRipple : nextUiMotion.wideIdleLoop)({ jelly });

    if (props.look === "tile") {
      const label = makeView(scene, (b) =>
        b.text({
          text: props.label,
          style: { fontFamily, fontSize: `${labelFontSize}px`, color: textColor },
        }),
      ).setOrigin(0.5);
      this.add(label);

      makeAlign((align) => align.anchor(zone).center(label));
      this.labelText = label;
      this.gameState.labelRestY = label.y;
    }

    this.setName(`next-ui-button-${props.look}`);

    addJellyButtonBehavior({
      obj: this,
      jelly,
      /** Круглая играет анимации по умолчанию; широкая плитка — мягкие, иначе край ломается */
      motion: isRound ? undefined : nextUiMotion.wideButton,
      clickOn: "release",
      onClick,
      onPress: () => this.moveLabel(this.gameState.labelRestY + nextUiConfig.labelPressPx),
      onRelease: () => this.moveLabel(this.gameState.labelRestY, true),
      onEnabledChange: (enabled) => this.setAlpha(enabled ? 1 : disabledAlpha),
    });
  }

  /** Снимает tween подписи; дети уничтожаются вместе с контейнером. */
  destroy(fromScene?: boolean) {
    const { labelText } = this;
    if (labelText) this.props.scene.tweens?.killTweensOf(labelText);
    super.destroy(fromScene);
  }

  /** Включает и выключает кнопку: выключенная тускнеет и не реагирует. */
  setEnabled(enabled: boolean) {
    this.setData("enabled", enabled);
  }

  /** Подпись плавно уходит на высоту y: вниз — быстро, обратно — пружиной. */
  private moveLabel(y: number, isSpring = false) {
    const { scene } = this.props;
    const { labelText } = this;
    if (!labelText) return;

    scene.tweens.killTweensOf(labelText);
    scene.tweens.add({
      targets: labelText,
      y,
      duration: isSpring ? 360 : 70,
      ease: isSpring ? "Elastic.Out" : "Quad.Out",
      ...(isSpring && { easeParams: [1.1, 0.4] }),
    });
  }
}
