import { jellyOutlineConfig } from "./config";
import type { IJellyOutlineConfig, IOutlineWave } from "./types";

interface IJellyOutlineProps {
  scene: Phaser.Scene;
  /** внешний размер контура, px; центр контура — точка (0, 0) */
  width: number;
  height: number;
  /** скругление углов, px */
  cornerRadius: number;
  /** тонкая текстура линии: тянется вдоль контура, её высота — толщина линии */
  lineTextureKey: string;
  /** точки и неровность линии; не заданные поля — из jellyOutlineConfig */
  config?: Partial<IJellyOutlineConfig>;
}

/**
 * Живой контур: рисованная линия на Rope по скруглённому прямоугольнику.
 * Сам контур не двигается — он складывает волны (IOutlineWave) вдоль нормали каждый кадр.
 * Волны добавляют стратегии: JellyOutlineLoops (приливы покоя) и JellyOutlineMotions (волна удара).
 * Точки пересчитывает один бесконечный tween — без update сцены.
 */
export class JellyOutline extends Phaser.GameObjects.Rope {
  private readonly base: Phaser.Math.Vector2[];
  private readonly normals: Phaser.Math.Vector2[];
  /** Те же объекты, что в points у Rope, но с типом Vector2 */
  private readonly loop: Phaser.Math.Vector2[];
  /** Волны, которые сейчас двигают контур; порядок — порядок добавления */
  private readonly waves: IOutlineWave[] = [];
  /** Бесконечный tween пересчёта точек */
  private readonly tick = { t: 0 };

  constructor(private props: IJellyOutlineProps) {
    const config: IJellyOutlineConfig = { ...jellyOutlineConfig, ...props.config };
    const base = createRoughLoop(props.width, props.height, props.cornerRadius, config);
    /** Замкнутая линия: последняя точка повторяет первую */
    const points = [...base, base[0]].map((p) => p.clone());
    super(props.scene, 0, 0, props.lineTextureKey, undefined, points, true);

    this.base = base;
    this.loop = points;
    this.normals = createNormals(base);

    const { scene } = props;
    scene.tweens.add({
      targets: this.tick,
      t: 1,
      duration: 1000,
      repeat: -1,
      onUpdate: () => {
        const timeMs = scene.time.now;
        this.waves.forEach((wave) => wave.sample(timeMs));
        this.applyPoints();
      },
    });
  }

  /** Снимает tween пересчёта и tween-ы волн (волна сама цель своего tween-а). */
  destroy(fromScene?: boolean) {
    this.scene?.tweens.killTweensOf([this.tick, ...this.waves]);
    super.destroy(fromScene);
  }

  /** Добавляет волну: со следующего кадра она двигает контур. */
  addWave(wave: IOutlineWave) {
    this.waves.push(wave);
  }

  /** Убирает волну: со следующего кадра её нет. */
  removeWave(wave: IOutlineWave) {
    const index = this.waves.indexOf(wave);
    if (index >= 0) this.waves.splice(index, 1);
  }

  /** Индекс точки контура, ближайшей к (x, y); координаты — локальные, от центра контура. */
  nearestPointIndex(x: number, y: number): number {
    let best = 0;
    let bestDistance = Infinity;
    this.base.forEach((p, i) => {
      const distance = Phaser.Math.Distance.Squared(p.x, p.y, x, y);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = i;
      }
    });
    return best;
  }

  /** Точки = рисованная основа + сумма смещений всех волн вдоль нормали. */
  private applyPoints() {
    const { base, normals, waves, loop } = this;
    const count = base.length;

    for (let i = 0; i < count; i++) {
      let offset = 0;
      for (const wave of waves) offset += wave.offsetPx(i, count);
      loop[i].set(base[i].x + normals[i].x * offset, base[i].y + normals[i].y * offset);
    }

    loop[count].copy(loop[0]);
    this.setDirty();
  }
}

/**
 * Точки по скруглённому прямоугольнику с равным шагом по длине,
 * плюс медленная неровность вдоль нормали — линия выглядит нарисованной от руки.
 */
function createRoughLoop(
  width: number,
  height: number,
  cornerRadius: number,
  config: IJellyOutlineConfig,
): Phaser.Math.Vector2[] {
  const { points: loopPoints, roughnessPx } = config;
  const path = createRoundRectPath(width, height, cornerRadius);
  const smooth = path.getSpacedPoints(loopPoints).slice(0, loopPoints);
  const normals = createNormals(smooth);
  const seedA = Math.random() * Math.PI * 2;
  const seedB = Math.random() * Math.PI * 2;

  return smooth.map((p, i) => {
    const t = (i / loopPoints) * Math.PI * 2;
    /** 2–3 пологие волны на сторону, как у линии от руки; гармоники целые — шва нет */
    const rough = roughnessPx * (Math.sin(t * 9 + seedA) * 0.6 + Math.sin(t * 13 + seedB) * 0.4);
    return new Phaser.Math.Vector2(p.x + normals[i].x * rough, p.y + normals[i].y * rough);
  });
}

/** Скруглённый прямоугольник с центром в (0, 0) как Phaser.Curves.Path. */
function createRoundRectPath(width: number, height: number, radius: number): Phaser.Curves.Path {
  const left = -width / 2;
  const top = -height / 2;
  const right = width / 2;
  const bottom = height / 2;
  const path = new Phaser.Curves.Path(left + radius, top);

  path.lineTo(right - radius, top);
  path.add(new Phaser.Curves.Ellipse(right - radius, top + radius, radius, radius, 270, 360));
  path.lineTo(right, bottom - radius);
  path.add(new Phaser.Curves.Ellipse(right - radius, bottom - radius, radius, radius, 0, 90));
  path.lineTo(left + radius, bottom);
  path.add(new Phaser.Curves.Ellipse(left + radius, bottom - radius, radius, radius, 90, 180));
  path.lineTo(left, top + radius);
  path.add(new Phaser.Curves.Ellipse(left + radius, top + radius, radius, radius, 180, 270));
  return path;
}

/** Нормали петли наружу: перпендикуляр к хорде соседей, развёрнутый от центра. */
function createNormals(points: Phaser.Math.Vector2[]): Phaser.Math.Vector2[] {
  const count = points.length;
  return points.map((p, i) => {
    const prev = points[(i - 1 + count) % count];
    const next = points[(i + 1) % count];
    const normal = new Phaser.Math.Vector2(next.y - prev.y, prev.x - next.x).normalize();
    if (normal.dot(p) < 0) normal.negate();
    return normal;
  });
}
