import type { IJellyLoop } from "../../shared/types";
import type { IJellyOutlineLoopArgs } from "../types";
import { createRandom, createSmoothNoise } from "../../shared/random";

/** Настройки приливов. */
export interface ILoopTidesOptions {
  /** высота горба в самый высокий момент, px; по умолчанию 25 */
  tideHeightMaxPx?: number;
  /** высота горба в самый низкий момент, px; по умолчанию 7.5 */
  tideHeightMinPx?: number;
  /** кругов по периметру в секунду; 0.1 — один круг за 10 секунд; по умолчанию 0.1 */
  tideLapsPerSec?: number;
  /** узость горба: 1 — очень широкий, чем больше, тем уже; 4 — около четверти периметра; по умолчанию 4 */
  tideNarrowness?: number;
  /** высота каждого горба всё время плавно едет к новой случайной цели между min и max px; один переезд, мс; по умолчанию 4000–9000 */
  tideChangeMinMs?: number;
  tideChangeMaxMs?: number;
  /** после stop() приливы гаснут, мс; по умолчанию 600 */
  fadeMs?: number;
}

/**
 * Приливы, как от Луны: два мягких горба на противоположных краях контура медленно едут по кругу,
 * высота каждого плавно меняется. stop() — горбы гаснут, волна убирается с контура.
 */
export function loopTides(args: IJellyOutlineLoopArgs & ILoopTidesOptions): IJellyLoop {
  const {
    outline,
    tideHeightMaxPx = 25,
    tideHeightMinPx = 7.5,
    tideLapsPerSec = 0.1,
    tideNarrowness = 4,
    tideChangeMinMs = 4000,
    tideChangeMaxMs = 9000,
    fadeMs = 600,
  } = args;
  /** у каждого горба свой плавный шум высоты 0..1 */
  const heightA = createSmoothNoise(createRandom(Math.random() * 4294967296), tideChangeMinMs, tideChangeMaxMs);
  const heightB = createSmoothNoise(createRandom(Math.random() * 4294967296), tideChangeMinMs, tideChangeMaxMs);

  /** Мутируется в sample: угол «Луны» и высоты горбов на кадр; weight гаснет до 0 после stop() */
  const wave = {
    weight: 1,
    moonAngle: 0,
    tideA: 0,
    tideB: 0,
    sample: (timeMs: number) => {
      wave.moonAngle = (timeMs / 1000) * tideLapsPerSec * Math.PI * 2;
      wave.tideA = tideHeightMinPx + (tideHeightMaxPx - tideHeightMinPx) * heightA(timeMs);
      wave.tideB = tideHeightMinPx + (tideHeightMaxPx - tideHeightMinPx) * heightB(timeMs);
    },
    /** Горб — степень от косинуса угла: он гладкий и по замкнутому кругу сам сходится без шва */
    offsetPx: (pointIndex: number, pointCount: number) => {
      const u = (pointIndex / pointCount) * Math.PI * 2;
      return (
        wave.weight *
        (wave.tideA * tideHump(u, wave.moonAngle, tideNarrowness) +
          wave.tideB * tideHump(u, wave.moonAngle + Math.PI, tideNarrowness))
      );
    },
  };
  outline.addWave(wave);

  return {
    kind: "loop",
    stop: () => {
      outline.scene.tweens.add({
        targets: wave,
        weight: 0,
        duration: fadeMs,
        ease: "Sine.Out",
        onComplete: () => outline.removeWave(wave),
      });
    },
  };
}

/** Мягкий горб 0..1 с центром в angle; power больше — горб уже. */
function tideHump(angle: number, center: number, power: number): number {
  return Math.pow(0.5 + 0.5 * Math.cos(angle - center), power);
}
