import { loopEdgeRipple } from "./loops/loopEdgeRipple";
import { loopEdgeWave } from "./loops/loopEdgeWave";

/**
 * Бесконечные желейные анимации — слоты JellyLoopStart; конечные — в JellyMotions.
 * Имя каждой начинается с loop: и в конфиге, и в стеке вызовов видно, что у неё нет конца.
 * Запуск возвращает IJellyLoop — его stop() мягко гасит то, что loop добавил к форме.
 * Своя настройка объекта — замыкание в конфиге: (args) => JellyLoops.loopEdgeRipple({ edgeOffsetMaxPx: 3, ...args }).
 *
 * Расширение: новый loop — свой файл в loops/ и строка здесь.
 */
export class JellyLoops {
  /** Живая рябь края в покое, свой узор у каждого объекта; stop() — край в покой */
  static readonly loopEdgeRipple = loopEdgeRipple;
  /** Колыхание края, например при наведении; stop() — волны гаснут */
  static readonly loopEdgeWave = loopEdgeWave;
}
