/** Общие приёмы рисования «рисованных» текстур на canvas: только на этапе создания текстур. */

export function toRgba(color: number, alpha = 1): string {
  const { red, green, blue } = Phaser.Display.Color.IntegerToColor(color);
  return `rgba(${red}, ${green}, ${blue}, ${alpha})`;
}

/** Шрифт canvas в стиле макета: вес задан самим файлом шрифта. */
export function canvasFont(size: number, family: string): string {
  return `${Math.round(size)}px ${family}`;
}

/**
 * Скруглённый квадрат с чуть выпуклыми сторонами, как рисованная плитка макета.
 * bulge — на сколько px середина стороны выходит наружу (контрольная точка — вдвое дальше).
 */
export function softRectPath(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
  bulge: number,
) {
  const b = bulge * 2;
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.quadraticCurveTo(x + w / 2, y - b, x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.quadraticCurveTo(x + w + b, y + h / 2, x + w, y + h - r);
  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.quadraticCurveTo(x + w / 2, y + h + b, x + r, y + h);
  ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.quadraticCurveTo(x - b, y + h / 2, x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

/**
 * Рисованный «блоб» по центру (cx, cy): суперэллипс с медленной неровностью радиуса.
 * power 2 — эллипс, больше — ближе к прямоугольнику; круг кнопки — power 2 и rx = ry.
 */
export function blobPath(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  rx: number,
  ry: number,
  power: number,
  roughness: number,
  seed: number,
) {
  const steps = 96;
  ctx.beginPath();
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * Math.PI * 2;
    const cos = Math.cos(t);
    const sin = Math.sin(t);
    const k = 1 + roughness * (Math.sin(t * 2 + seed) * 0.6 + Math.sin(t * 3 - seed * 1.7) * 0.4);
    const x = cx + rx * k * Math.sign(cos) * Math.abs(cos) ** (2 / power);
    const y = cy + ry * k * Math.sign(sin) * Math.abs(sin) ** (2 / power);
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

/**
 * Заливка с мягким краем, как акварель: фигура рисуется далеко за холстом,
 * а на место попадает только её размытая тень. Работает во всех браузерах, в отличие от ctx.filter.
 */
export function fillSoft(
  ctx: CanvasRenderingContext2D,
  color: number,
  blur: number,
  path: (dx: number) => void,
) {
  const far = ctx.canvas.width * 4;
  ctx.save();
  ctx.shadowColor = toRgba(color);
  ctx.shadowBlur = blur;
  ctx.shadowOffsetX = far;
  path(-far);
  ctx.fillStyle = "#000";
  ctx.fill();
  ctx.restore();
}

/** Рисованная обводка: чёткая линия и мягкий ореол того же цвета. */
export function strokeSoft(ctx: CanvasRenderingContext2D, color: number, width: number) {
  ctx.lineJoin = "round";
  ctx.lineWidth = width + 2.5;
  ctx.strokeStyle = toRgba(color, 0.25);
  ctx.stroke();
  ctx.lineWidth = width;
  ctx.strokeStyle = toRgba(color);
  ctx.stroke();
}
