import { JellyMesh } from "../../../../../common/animation/animation-jelly";
import { next2048Config } from "../../../config";
import { Next2048Textures } from "../../../shared/Next2048Textures/Next2048Textures";
import { jellyTileMotion } from "./jellyTileMotion";

interface IJellyTileProps {
  scene: Phaser.Scene;
  value: number;
  x: number;
  y: number;
}

/**
 * Желейная плитка: появление, езда с инерцией, поглощение и слияние; в покое край «кипит».
 * Анимации формы — слоты jellyTileMotion (JellyMotions и JellyLoops); плитка решает только, когда и какую играть.
 */
export class JellyTile extends JellyMesh {
  /**
   * Меняющееся состояние плитки: текущий номинал и tween езды.
   * Новый ход останавливает только прежнюю езду: чужие tween-ы объекта (растворение при поглощении) не трогаются.
   */
  private readonly gameState: { value: number; rideTween?: Phaser.Tweens.Tween };

  constructor(private props: IJellyTileProps) {
    const { scene, value, x, y } = props;
    super({
      scene,
      x,
      y,
      textureKey: Next2048Textures.tile(value),
      width: Next2048Textures.tileSize,
      height: Next2048Textures.tileSize,
    });
    this.gameState = { value };
    jellyTileMotion.idleLoop({ jelly: this });
  }

  /** Появление новой плитки. */
  playSpawn() {
    jellyTileMotion.spawnAnimation({ jelly: this });
  }

  /**
   * Езда в клетку: по ходу плитка тянется (инерция), а у цели шлёпается и пружинит.
   * dirX/dirY — направление на экране (y вниз); land = false — без шлепка, форму у цели задаст слияние.
   * Время езды — игровое moveMs: его получает и анимация растяжения.
   */
  playMove(
    toX: number,
    toY: number,
    dirX: number,
    dirY: number,
    land: boolean,
    onArrive?: () => void,
  ) {
    const { moveMs } = next2048Config;
    const { moveAnimation, landAnimation } = jellyTileMotion;
    const { scene } = this.props;
    const { gameState } = this;
    const direction = { x: dirX, y: dirY };

    /** Прежняя езда обрывается без onComplete: её прибытие и шлепок уже не нужны */
    gameState.rideTween?.stop();
    moveAnimation({ jelly: this, direction, durationMs: moveMs });
    gameState.rideTween = scene.tweens.add({
      targets: this,
      x: toX,
      y: toY,
      duration: moveMs,
      ease: "Quad.In",
      onComplete: () => {
        onArrive?.();
        if (land) landAnimation({ jelly: this, direction });
      },
    });
  }

  /** Поглощение: влипает в соседа и тает; onComplete — когда растаяла. Уложить её под соседа должен владелец. */
  playAbsorb(onComplete: () => void) {
    jellyTileMotion.absorbAnimation({ jelly: this, onComplete });
  }

  /**
   * Слияние: плитку вдавливает удар соседа, в пике сплющивания меняется номинал,
   * затем она пружинит и колышется, как нажатая желейная кнопка.
   * dirX/dirY — откуда пришёл удар на экране (y вниз): плитка сплющивается по нему.
   */
  playMerge(value: number, dirX: number, dirY: number) {
    const { mergePressAnimation, mergeReleaseAnimation } = jellyTileMotion;

    /** Вдавливание идёт от текущей формы и забирает её себе: растяжение от езды сходит в него без щелчка */
    mergePressAnimation({
      jelly: this,
      direction: { x: dirX, y: dirY },
      onComplete: () => {
        this.setValue(value);
        mergeReleaseAnimation({ jelly: this });
      },
    });
  }

  /** Меняет номинал. Текстуры номиналов одного размера и на весь canvas, поэтому UV те же — сетку не пересобираем. */
  setValue(value: number) {
    const { gameState } = this;
    if (value === gameState.value) return;
    gameState.value = value;

    this.setTexture(Next2048Textures.tile(value));
  }
}
