import { HtmlRoot, iosResumePatch } from "@kvisaz/phaser-common";
import { phaserGameConfig } from "./configs/config";
import { BootScene } from "./scenes/Boot";
import { Next2048Scene } from "./scenes/Next2048Scene";
import { ServicesScene } from "./scenes/ServicesScene";
import { removeContextMenu, setupGameLocale } from "./scenes/Boot/setupBoot";

/** Запускает обычный Phaser.Game: собственные сцены, общие сервисы лежат в `services/`. */
export function startGame(): Phaser.Game {
  HtmlRoot.root = document.getElementById("game")!;

  const game = new Phaser.Game({
    ...phaserGameConfig,
    scene: [BootScene, ServicesScene, Next2048Scene],
  });

  iosResumePatch(game);
  removeContextMenu();
  setupGameLocale();
  return game;
}
