import { jellyMeshConfig } from "./config";
import type { IJellyMeshConfig } from "./types";
import { createLivelyWaves, type ILivelyProfile, type LivelyWaves } from "./livelyWaves";

interface IJellyMeshProps {
  scene: Phaser.Scene;
  x: number;
  y: number;
  textureKey: string;
  /** размер Mesh в px = размер текстуры: сетка 1×1 растягивается на него */
  width: number;
  height: number;
  /** сетка желе; не заданные поля — из jellyMeshConfig */
  config?: Partial<IJellyMeshConfig>;
}

/**
 * Числа, которыми tween-ы управляют формой. Все — доли размера объекта, 0 — покой:
 * то, что задано, то и видно — например, squash 0.25 сплющивает на четверть размера.
 * Мутируются tween-ами напрямую, после каждого шага форма пересчитывается в вершины.
 */
export interface IJellyShape {
  /** растяжение вдоль движения, доля размера: задний край отстаёт */
  stretch: number;
  /** сплющивание вдоль движения, доля размера; Elastic уводит его в минус — форма пружинит */
  squash: number;
  /** раздувание сторон из центра, доля размера */
  bulge: number;
  /** общий масштаб: рост при появлении, сжатие при поглощении; 1 — покой */
  grow: number;
  /** сила бегущих волн по краю, доля радиуса */
  wobble: number;
  /** фаза бегущих волн, рад */
  phase: number;
  /** направление движения на экране (y вниз); не (0, 0) — иначе поворот схлопнет форму */
  dirX: number;
  dirY: number;
}

/** Всё, что у вершины не меняется: считается один раз при постройке сетки. */
interface IVertexBase {
  x: number;
  y: number;
  /** 0 в центре, 1 на краю, в квадрате: деформации живут у краёв */
  edge2: number;
  /** вершина на самом краю: по таким ищется пик живой ряби */
  onEdge: boolean;
  /** 1 в середине стороны, 0 в углу: стороны выгибаются сильнее углов */
  side: number;
  /** угол вершины от центра: по нему считается живая рябь края */
  angle: number;
  /** sin/cos угла вершины × число волн: волны считаются без тригонометрии на вершину */
  s1: number;
  c1: number;
  s2: number;
  c2: number;
}

/** Живая рябь на текущий кадр: узор по вершинам и перевод единицы узора в сдвиг модели по осям. */
interface IRippleFrame {
  values: number[];
  scaleX: number;
  scaleY: number;
}

/**
 * Желе: картинка на сетке Mesh, края которой двигаются как живые.
 * Форму меняют tween-ы и живая рябь края (startIdle); пока формы никто не трогает, Mesh не пересчитывает вершины.
 * Готовые анимации формы — JellyMotions (конечные) и JellyLoops (loop); сам Mesh даёт animate, setShape, setDirection, stopShape, startIdle и stopIdle.
 */
export class JellyMesh extends Phaser.GameObjects.Mesh {
  readonly shape: IJellyShape = {
    stretch: 0,
    squash: 0,
    bulge: 0,
    grow: 1,
    wobble: 0,
    phase: 0,
    dirX: 1,
    dirY: 0,
  };
  private readonly meshConfig: IJellyMeshConfig;
  private base: IVertexBase[] = [];
  /** Меняется только вместе с узором волн (updateRipple), раз за кадр; applyShape его только читает */
  private ripple: IRippleFrame = { values: [], scaleX: 0, scaleY: 0 };
  private sleepTimer?: Phaser.Time.TimerEvent;
  /** Меняющееся состояние живой ряби: свои волны объекта и tween, который их показывает; пока рябь есть, Mesh не засыпает */
  private readonly idleState: {
    waves?: LivelyWaves;
    tween?: Phaser.Tweens.Tween;
  } = {};

  constructor(meshProps: IJellyMeshProps) {
    const { scene, x, y, textureKey, width, height, config } = meshProps;
    super(scene, x, y, textureKey);
    this.meshConfig = { ...jellyMeshConfig, ...config };

    /** Орто-проекция: вершина ±0.5 попадает ровно на край текстуры */
    this.setSize(width, height);
    this.setOrtho(1, 1);
    this.hideCCW = false;
    this.buildGrid();
  }

  /** Снимает tween-ы формы и таймеры. */
  destroy(fromScene?: boolean) {
    this.scene?.tweens.killTweensOf([this, this.shape]);
    this.sleepTimer?.remove();
    this.idleState.tween?.stop();
    super.destroy(fromScene);
  }

  /**
   * Tween чисел формы: будит Mesh, пересчитывает вершины каждый шаг, в конце укладывает спать.
   * onComplete — после последнего шага формы. Убийство tween-а снаружи не предусмотрено: onComplete тогда не придёт.
   */
  animate(
    to: Partial<IJellyShape>,
    duration: number,
    ease: string,
    options: { easeParams?: number[]; onComplete?: () => void } = {},
  ): Phaser.Tweens.Tween {
    const { easeParams, onComplete } = options;
    this.wake();
    return this.scene.tweens.add({
      targets: this.shape,
      ...to,
      duration,
      ease,
      ...(easeParams && { easeParams }),
      onUpdate: () => this.applyShape(),
      onComplete: () => {
        this.applyShape();
        this.sleepWhenIdle();
        onComplete?.();
      },
    });
  }

  /** Мгновенно задаёт числа формы и перерисовывает. */
  setShape(values: Partial<IJellyShape>) {
    Object.assign(this.shape, values);
    this.refresh();
  }

  /** Задаёт ось деформаций на экране (y вниз) без пересчёта: её применит следующая смена формы. */
  setDirection(x: number, y: number) {
    Object.assign(this.shape, { dirX: x, dirY: y });
  }

  /**
   * Останавливает все tween-ы формы: новая анимация забирает форму себе.
   * Оборванные анимации не доходят до onComplete — звать, только когда прежняя анимация больше не нужна.
   */
  stopShape() {
    this.scene.tweens.killTweensOf(this.shape);
  }

  /**
   * Живая рябь края: свой узор волн и своя смена силы от своего генератора случайных чисел.
   * Край отходит от покоя на px из профиля; пересчёт — каждый кадр бесконечным tween-ом.
   * Повторный вызов заменяет прежнюю рябь; снаружи запускается через JellyLoops.loopEdgeRipple.
   */
  startIdle(profile: ILivelyProfile) {
    const { idleState, scene } = this;
    idleState.tween?.stop();
    idleState.waves = createLivelyWaves(profile, Math.random() * 4294967296);
    idleState.waves.sample(scene.time.now);
    this.updateRipple();

    this.wake();
    idleState.tween = scene.tweens.addCounter({
      from: 0,
      to: 1,
      duration: 1000,
      repeat: -1,
      onUpdate: () => {
        idleState.waves?.sample(scene.time.now);
        this.updateRipple();
        this.applyShape();
      },
    });
  }

  /** Останавливает живую рябь: край возвращается в покой, Mesh снова может заснуть. */
  stopIdle() {
    const { idleState } = this;
    idleState.tween?.stop();
    idleState.tween = undefined;
    idleState.waves = undefined;
    this.updateRipple();
    this.refresh();
  }

  private buildGrid() {
    const { segments: meshSegments, wobbleWaves } = this.meshConfig;
    Phaser.Geom.Mesh.GenerateGridVerts({
      mesh: this,
      texture: this.texture.key,
      width: 1,
      height: 1,
      widthSegments: meshSegments,
      heightSegments: meshSegments,
    });

    this.base = this.vertices.map(({ x, y }) => {
      const angle = Math.atan2(y, x);
      const edge = Math.min(1, Math.max(Math.abs(x), Math.abs(y)) * 2);
      return {
        x,
        y,
        edge2: edge * edge,
        onEdge: edge > 0.999,
        side: 1 - Math.abs(x * y) * 4,
        angle,
        s1: Math.sin(angle * wobbleWaves),
        c1: Math.cos(angle * wobbleWaves),
        s2: Math.sin(angle * (wobbleWaves + 2)),
        c2: Math.cos(angle * (wobbleWaves + 2)),
      };
    });
    this.ripple = { values: this.base.map(() => 0), scaleX: 0, scaleY: 0 };
    this.applyShape();
  }

  /**
   * Живая рябь на кадр: узор по вершинам и его пик по краю. Узор меняется только в sample волн,
   * поэтому считается сразу после него, а все applyShape кадра его переиспользуют.
   * Пик приводится ровно к edgeOffsetPx, px переводятся в модель отдельно по осям:
   * край капсулы отходит на те же px, что у квадрата.
   *
   * TODO: проверить позже кейс — две волны с одинаковым числом гребней почти гасят друг друга.
   * Пик тогда близок к нулю, нормировка раздувает остаток до полной силы, и узор может рывком сменить фазу.
   * Визуально пока не замечено; если появится — нижняя граница пика (доля от суммы весов волн)
   * или разные числа гребней у живых волн.
   */
  private updateRipple() {
    const { waves } = this.idleState;
    const { base, ripple, width, height } = this;
    const { values } = ripple;

    let peak = 0;
    for (let i = 0; i < base.length; i++) {
      const v = base[i];
      values[i] = waves ? waves.value(v.angle) : 0;
      if (v.onEdge) peak = Math.max(peak, Math.abs(values[i]));
    }
    /** px края на единицу узора, удвоено: край модели — ±0.5 */
    const px = waves && peak > 1e-6 ? (2 * waves.edgeOffsetPx) / peak : 0;
    ripple.scaleX = px / width;
    ripple.scaleY = px / height;
  }

  /**
   * Форма → вершины. Все слагаемые считаются от вершины в покое, ошибка не копится.
   * Синусы фаз — по 4 на весь Mesh, на вершину — только умножения.
   */
  private applyShape() {
    const { stretch, squash, bulge, grow, wobble, phase, dirX } = this.shape;
    const { vertices, base } = this;
    const { values: rippleValues, scaleX: rippleX, scaleY: rippleY } = this.ripple;
    /** модель Mesh: y вверх */
    const dirY = -this.shape.dirY;

    /** sin(nA + p) = sin(nA)·cos(p) + cos(nA)·sin(p): фазы — один раз на кадр */
    const pc = Math.cos(phase);
    const ps = Math.sin(phase);
    const qc = Math.cos(-phase * 1.3);
    const qs = Math.sin(-phase * 1.3);

    for (let i = 0; i < vertices.length; i++) {
      const v = base[i];

      /** вдоль движения (along) и поперёк (across), край = ±0.5 */
      const along = v.x * dirX + v.y * dirY;
      const across = -v.x * dirY + v.y * dirX;

      /** Инерция: задний край отстаёт, форма вытягивается и худеет поперёк */
      let a = along - (0.5 - along) * stretch * 0.5;
      let c = across * (1 - stretch * 0.5);

      /** Шлепок: сплющивание вдоль хода, раздача вширь */
      a *= 1 - squash;
      c *= 1 + squash * 0.8;

      /** Раздувание и бегущие волны анимаций (wobble) */
      const wave = wobble * (0.6 * (v.s1 * pc + v.c1 * ps) + 0.4 * (v.s2 * qc + v.c2 * qs));
      const k = (1 + bulge * v.side) * (1 + wave * v.edge2) * grow;

      /** Живая рябь края (idle): сдвиг в px, одинаковый по обеим осям */
      const rippleK = rippleValues[i] * v.edge2;

      vertices[i].x = (a * dirX - c * dirY) * k * (1 + rippleK * rippleX);
      vertices[i].y = (a * dirY + c * dirX) * k * (1 + rippleK * rippleY);
    }
  }

  /** Одиночная смена формы без tween-а: пересчитать, разбудить и уложить спать. */
  private refresh() {
    this.applyShape();
    this.wake();
    this.sleepWhenIdle();
  }

  /** Mesh пересчитывает вершины каждый кадр, только пока форма меняется. */
  private wake() {
    this.sleepTimer?.remove();
    this.sleepTimer = undefined;
    this.ignoreDirtyCache = true;
  }

  /** Через пару кадров после последнего изменения: форма уже посчитана, пересчёт можно выключить. */
  private sleepWhenIdle() {
    this.sleepTimer?.remove();
    this.sleepTimer = this.scene.time.delayedCall(this.meshConfig.sleepMs, () => {
      if (this.idleState.waves || this.scene.tweens.isTweening(this.shape)) return;
      this.ignoreDirtyCache = false;
    });
  }
}
