import { generateRuntimeTextures, loadFont } from "@kvisaz/phaser-common";
import { next2048Config } from "../../config";
import {
  drawLineTexture,
  drawSlotTexture,
  drawTileTexture,
  getTileColors,
  lineTextureHeight,
  tileTextureSize,
} from "./drawBoardTextures";
import {
  buttonTextureSize,
  drawButtonTexture,
  drawPillTexture,
  pillTextureHeight,
  pillTextureWidth,
  type ButtonIcon,
} from "./drawUiTextures";

export type { ButtonIcon };

/**
 * Текстуры нового дизайна: имена, размеры и одна генерация на всю игру.
 * preload — в preload Boot, generate — один раз в create Boot (в Storybook — в StoryScene);
 * компоненты только берут текстуры по именам отсюда и ничего не рисуют.
 */
export class Next2048Textures {
  static readonly tileSize = tileTextureSize;
  static readonly slot = "next2048_slot";
  static readonly line = "next2048_line";
  static readonly lineHeight = lineTextureHeight;
  static readonly buttonSize = buttonTextureSize;
  static readonly pillWidth = pillTextureWidth;
  static readonly pillHeight = pillTextureHeight;
  static readonly pillScore = "next2048_pill_score";
  static readonly pillBest = "next2048_pill_best";

  static tile(value: number): string {
    return `next2048_tile_${value}`;
  }

  static button(icon: ButtonIcon): string {
    return `next2048_button_${icon}`;
  }

  /** Цвета плитки по номиналу: нужны и вне текстур, например каплям при слиянии. */
  static tileColors(value: number) {
    return getTileColors(value);
  }

  /** Грузит шрифт, которым рисуются цифры текстур: вызывать в preload до generate. */
  static preload(scene: Phaser.Scene) {
    const { fontFamily, fontUrl } = next2048Config;
    loadFont({ scene, fontFamily, url: fontUrl });
  }

  /** Рисует все текстуры экрана; повторный вызов ничего не делает. Шрифт Nunito к этому моменту уже загружен. */
  static generate(scene: Phaser.Scene) {
    const { cellSize, maxTileValue, scorePill, bestPill } = next2048Config;
    const tileValues = Array.from({ length: Math.log2(maxTileValue) }, (_, i) => 2 ** (i + 1));
    const icons: ButtonIcon[] = ["restart", "undo", "menu"];

    generateRuntimeTextures({
      scene,
      textures: [
        ...tileValues.map((value) => ({
          textureName: Next2048Textures.tile(value),
          width: tileTextureSize,
          height: tileTextureSize,
          generatorFn: ({ context }: { context: CanvasRenderingContext2D }) =>
            drawTileTexture(context, value),
        })),
        {
          textureName: Next2048Textures.slot,
          width: cellSize,
          height: cellSize,
          generatorFn: ({ context }) => drawSlotTexture(context),
        },
        {
          textureName: Next2048Textures.line,
          width: 8,
          height: lineTextureHeight,
          generatorFn: ({ context }) => drawLineTexture(context),
        },
        ...icons.map((icon) => ({
          textureName: Next2048Textures.button(icon),
          width: buttonTextureSize,
          height: buttonTextureSize,
          generatorFn: ({ context }: { context: CanvasRenderingContext2D }) =>
            drawButtonTexture(context, icon),
        })),
        {
          textureName: Next2048Textures.pillScore,
          width: pillTextureWidth,
          height: pillTextureHeight,
          generatorFn: ({ context }) => drawPillTexture(context, scorePill, 1.3),
        },
        {
          textureName: Next2048Textures.pillBest,
          width: pillTextureWidth,
          height: pillTextureHeight,
          generatorFn: ({ context }) => drawPillTexture(context, bestPill, 4.1),
        },
      ],
    });
  }
}
