import type { INext2048Save, IPlayerData, ISoundState, SoundSave } from "./types";

/**
 * Мост между компактным форматом сохранения и обычными данными игры:
 * чистые функции, сохранение не трогают.
 */

/** Чистит загруженное сохранение: битые поля отбрасываются, остальное остаётся. */
export function sanitizeSave(data: INext2048Save | undefined): INext2048Save {
  if (data == null || typeof data !== "object") return {};
  return {
    ...(Array.isArray(data.s) ? { s: [data.s[0] ? 1 : 0, data.s[1] ? 1 : 0] } : {}),
  };
}

export function toSound([sound, music]: SoundSave): ISoundState {
  return { isSoundOn: sound === 1, isMusicOn: music === 1 };
}

export function fromSound({ isSoundOn, isMusicOn }: ISoundState): SoundSave {
  return [isSoundOn ? 1 : 0, isMusicOn ? 1 : 0];
}

/** Данные игрока из загруженного (уже очищенного) сохранения: недостающее — по умолчанию. */
export function toPlayerData(save: INext2048Save): IPlayerData {
  return {
    sound: save.s ? toSound(save.s) : undefined,
  };
}

/** Компактное сохранение из данных игрока: значения по умолчанию не пишутся. Вызывается на каждую запись. */
export function fromPlayerData(data: IPlayerData): INext2048Save {
  const { sound } = data;
  const save: INext2048Save = {};
  if (sound) save.s = fromSound(sound);
  return save;
}
