import { createRandom, createSmoothNoise } from "../shared/random";

/**
 * Живая рябь контура: у каждого объекта свой генератор случайных чисел,
 * поэтому узор волн, их бег и смена силы нигде не совпадают и не повторяются.
 * Волны задают только узор — где гребни; насколько отходит край, задаёт профиль в px.
 */

/** Профиль ряби для типа объекта: видимые ориентиры, из диапазонов генератор объекта берёт свои числа. */
export interface ILivelyProfile {
  /** край в самый бурный момент отходит от покоя на столько, px; углы — примерно в √2 раза дальше */
  edgeOffsetMaxPx: number;
  /** край в самый тихий момент, px */
  edgeOffsetMinPx: number;
  /** сила ряби всё время плавно едет к новой случайной цели между min и max px; один такой переезд длится, мс */
  calmChangeMinMs: number;
  calmChangeMaxMs: number;
  /** гребней волны по контуру, целое — контур замкнут без шва */
  crestCountMin: number;
  crestCountMax: number;
  /** гребень обходит контур за столько секунд; направление случайное */
  crestLapMinSec: number;
  crestLapMaxSec: number;
  /** узор одной волны рождается и гаснет за столько мс, затем его сменяет новый */
  waveLifeMinMs: number;
  waveLifeMaxMs: number;
}

/** Одна волна: живёт от bornMs до bornMs + lifeMs, её доля в узоре по жизни плавно растёт и гаснет. */
interface IWave {
  count: number;
  /** скорость фазы, рад/с: гребень обходит контур за 2π·count / |speed| секунд */
  speed: number;
  phase: number;
  bornMs: number;
  lifeMs: number;
}

/**
 * Три волны с разными жизнями складываются в узор; сила ряби в px плавно ходит между тихим и бурным.
 * sample(time) готовит волны и силу на момент времени, value(angle) — узор в точке контура
 * (не в px: владелец сам приводит его пик к edgeOffsetPx).
 */
export function createLivelyWaves(profile: ILivelyProfile, seed: number) {
  const random = createRandom(seed);
  const calm = createSmoothNoise(random, profile.calmChangeMinMs, profile.calmChangeMaxMs);
  const spawn = (bornMs: number): IWave => {
    const count = Math.round(random.range(profile.crestCountMin, profile.crestCountMax));
    const lapSec = random.range(profile.crestLapMinSec, profile.crestLapMaxSec);
    return {
      count,
      speed: ((Math.PI * 2 * count) / lapSec) * (random.next() < 0.5 ? -1 : 1),
      phase: random.range(0, Math.PI * 2),
      bornMs,
      lifeMs: random.range(profile.waveLifeMinMs, profile.waveLifeMaxMs),
    };
  };
  /** волны рождены в разное «прошлое»: с первого кадра они в разных точках жизни */
  const waves = [0, 1, 2].map(() => {
    const wave = spawn(0);
    wave.bornMs = -random.range(0, wave.lifeMs);
    return wave;
  });

  /** На момент времени: фаза и доля каждой волны в узоре */
  const current = waves.map(() => ({ count: 0, weight: 0, phase: 0 }));

  /** Мутируется в sample: edgeOffsetPx — сила ряби сейчас */
  const lively = {
    /** насколько сейчас отходит край в пике узора, px: между тихим и бурным моментом */
    edgeOffsetPx: profile.edgeOffsetMinPx,

    sample(timeMs: number) {
      const { edgeOffsetMinPx, edgeOffsetMaxPx } = profile;
      lively.edgeOffsetPx = edgeOffsetMinPx + (edgeOffsetMaxPx - edgeOffsetMinPx) * calm(timeMs);

      waves.forEach((wave, i) => {
        if (timeMs > wave.bornMs + wave.lifeMs) waves[i] = spawn(timeMs);
        const w = waves[i];
        const life = (timeMs - w.bornMs) / w.lifeMs;
        const c = current[i];
        c.count = w.count;
        c.weight = Math.sin(Math.PI * life);
        c.phase = w.phase + (w.speed * (timeMs - w.bornMs)) / 1000;
      });
    },

    value(angle: number) {
      let sum = 0;
      for (const c of current) sum += c.weight * Math.sin(c.count * angle + c.phase);
      return sum;
    },
  };
  return lively;
}

export type LivelyWaves = ReturnType<typeof createLivelyWaves>;
