import type { IJellyLoop } from "../../shared/types";
import type { IJellyLoopArgs } from "../types";

/** Настройки колыхания края. */
export interface ILoopEdgeWaveOptions {
  /** колыхание нарастает, мс; по умолчанию 250 */
  riseMs?: number;
  /** сила колыхания, доля радиуса; по умолчанию 0.0315 */
  edgeWaveShare?: number;
  /** волны бегут по краю: на столько радиан…; по умолчанию 200 */
  runPhase?: number;
  /** …за столько мс, если колыхание не остановят раньше; по умолчанию 30000 */
  runMs?: number;
  /** после stop() колыхание гаснет, мс; по умолчанию 300 */
  fadeMs?: number;
}

/**
 * Колыхание края — например, пока указатель над кнопкой: волны нарастают и бегут по краю.
 * stop() — бег волн останавливается, колыхание плавно гаснет.
 */
export function loopEdgeWave(args: IJellyLoopArgs & ILoopEdgeWaveOptions): IJellyLoop {
  const { jelly, riseMs = 250, edgeWaveShare = 0.0315, runPhase = 200, runMs = 30000, fadeMs = 300 } = args;

  jelly.animate({ wobble: edgeWaveShare }, riseMs, "Sine.Out");
  const run = jelly.animate({ phase: jelly.shape.phase + runPhase }, runMs, "Linear");

  return {
    kind: "loop",
    stop: () => {
      run.stop();
      jelly.animate({ wobble: 0 }, fadeMs, "Sine.Out");
    },
  };
}
