import type { IJellyMotionArgs } from "../types";

/** Настройки отпускания с пружиной. */
export interface ISpringReleaseOptions {
  /** колыхание края в начале, доля радиуса; по умолчанию 0.07 */
  edgeWaveShare?: number;
  /** пружина сплющивания: [амплитуда, период] у Elastic.Out; по умолчанию [1.4, 0.22] */
  squashSpringEase?: number[];
  /** пружина раздувания: [амплитуда, период] у Elastic.Out; по умолчанию [1.2, 0.3] */
  bulgeSpringEase?: number[];
  /** доля времени, за которую успокаивается раздувание; по умолчанию 0.8 */
  bulgeSettleTimeShare?: number;
  /** на сколько радиан пробегают волны края, пока колыхание затихает; по умолчанию 16 */
  edgeWavePhase?: number;
}

/**
 * Отпускание: сплющивание и раздувание пружинят с перехлёстом к покою, край долго колышется; по умолчанию 900 мс.
 * Прежние анимации формы не снимает: если нужно, вызывающий делает jelly.stopShape() сам.
 * Возвращает tween колыхания — он кончается последним.
 */
export function springReleaseMotion(args: IJellyMotionArgs & ISpringReleaseOptions): Phaser.Tweens.Tween {
  const {
    jelly,
    direction,
    durationMs = 900,
    edgeWaveShare = 0.07,
    squashSpringEase = [1.4, 0.22],
    bulgeSpringEase = [1.2, 0.3],
    bulgeSettleTimeShare = 0.8,
    edgeWavePhase = 16,
    onComplete,
  } = args;
  if (direction) jelly.setDirection(direction.x, direction.y);

  jelly.setShape({ wobble: edgeWaveShare });
  jelly.animate({ squash: 0 }, durationMs, "Elastic.Out", { easeParams: [...squashSpringEase] });
  jelly.animate({ bulge: 0 }, durationMs * bulgeSettleTimeShare, "Elastic.Out", {
    easeParams: [...bulgeSpringEase],
  });
  return jelly.animate(
    { wobble: 0, phase: jelly.shape.phase + edgeWavePhase },
    durationMs,
    "Sine.Out",
    { onComplete },
  );
}
