/**
 * Случайность для живых анимаций: генератор с зерном и плавный шум во времени.
 * У каждого объекта свой генератор — их движения не совпадают и не повторяются.
 */

/** Генератор случайных чисел с зерном (mulberry32). */
export function createRandom(seed: number) {
  let s = seed >>> 0;
  const next = () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return { next, range: (min: number, max: number) => min + (max - min) * next() };
}

export type SeededRandom = ReturnType<typeof createRandom>;

/**
 * Плавный шум во времени 0..1: значение всё время плавно едет к новой случайной цели,
 * один переезд длится случайно от gapMinMs до gapMaxMs; трогается и тормозит мягко.
 */
export function createSmoothNoise(random: SeededRandom, gapMinMs: number, gapMaxMs: number) {
  let from = random.next();
  let to = random.next();
  let start = 0;
  let gap = random.range(gapMinMs, gapMaxMs);

  return (timeMs: number) => {
    while (timeMs > start + gap) {
      from = to;
      to = random.next();
      start += gap;
      gap = random.range(gapMinMs, gapMaxMs);
    }
    const k = (timeMs - start) / gap;
    return from + (to - from) * (k * k * (3 - 2 * k));
  };
}
