import { onSceneShutdown, UnSubManager } from "@kvisaz/phaser-common";
import type { SafeEventsAdapter, SceneEvents } from "@kvisaz/phaser-common";

/** Одна связка событий: умеет подключаться и возвращает отписку только своего моста. */
export interface IEventLink {
  connect(): () => void;
}

/**
 * Связка «событие сцены → событие общей шины».
 * Без map данные передаются как есть, с map — преобразуются по пути.
 * Имена и payload проверяются по картам событий адаптеров.
 */
export function link<
  TSource extends object,
  TTarget extends object,
  TFrom extends Extract<keyof TSource, string>,
  TTo extends Extract<keyof TTarget, string>,
>(
  from: SceneEvents<TSource>,
  fromEvent: TFrom,
  to: SafeEventsAdapter<TTarget>,
  toEvent: TTo,
  map?: (data: TSource[TFrom]) => TTarget[TTo],
): IEventLink {
  return {
    connect: () =>
      from.on(fromEvent as Extract<keyof TSource, string | symbol>, (data) => {
        /** Без map события должны нести одинаковые данные — это проверяет вызывающий код. */
        const payload = map ? map(data as TSource[TFrom]) : (data as unknown as TTarget[TTo]);

        to.emit(
          toEvent as Extract<keyof TTarget, string | symbol>,
          payload as unknown as TTarget[Extract<keyof TTarget, string | symbol>],
        );
      }),
  };
}

interface IConnectLinksProps {
  scene: Phaser.Scene;
  links: IEventLink[];
}

/**
 * Подключает пачку связок и снимает их при выключении сцены.
 * Возвращает копилку, чтобы можно было отключить мосты раньше вручную.
 */
export function connectLinks({ scene, links }: IConnectLinksProps): UnSubManager {
  const unSubs = new UnSubManager();

  links.forEach((item) => unSubs.addUnSub(item.connect()));
  unSubs.addUnSub(onSceneShutdown(scene, () => unSubs.destroy()));

  return unSubs;
}
