import { SafeEventsAdapter, SceneEvents } from "@kvisaz/phaser-common";
import { connectLinks, link } from "../../common/events/connectEvents";
import type { IGameEvents } from "../../events";
import { SCENES } from "../../scenes";
import { services } from "../../services";
import { getLocalizedText } from "../../services/locale";
import { connectUiSounds } from "../shared/next-ui/connectUiSounds";
import { next2048Config } from "./config";
import { Next2048Dialogs } from "./Next2048Dialogs/Next2048Dialogs";
import { Next2048Screen } from "./Next2048Screen/Next2048Screen";
import type { INext2048BoardEvents } from "./Next2048Screen/Next2048Board/events";

/**
 * Новый дизайн, сцена игры по умолчанию: экран по макету.
 * Звук живёт в ServicesScene, сцена только пересылает игровые факты в общую шину.
 */
export class Next2048Scene extends Phaser.Scene {
  constructor() {
    super(SCENES.next2048);
  }

  create(): void {
    this.cameras.main.setBackgroundColor(next2048Config.backgroundColor);

    const dialogs = new Next2048Dialogs({ scene: this });
    const screen = new Next2048Screen({
      scene: this,
      scoreLabel: getLocalizedText("next2048Score"),
      bestLabel: getLocalizedText("next2048Best"),
      /** Новая игра — только после «Вы уверены?»; отмена хода — без диалога, прямо в поле */
      onRestart: () => dialogs.confirmNewGame(() => screen.board.newGame()),
      /** Пока «меню» открывает сразу настройки */
      onMenu: () => dialogs.openSettings(),
    });
    this.add.existing(screen);

    /** Сцена не играет звук сама: GameSoundService в ServicesScene слушает общую шину. */
    const soundEvents = new SafeEventsAdapter<IGameEvents>(services.gameEvents);
    const boardEvents = new SceneEvents<INext2048BoardEvents>({ scene: this });

    /** Звук кнопок — общим мостом next-ui: он же нужен каждой modal-сцене диалога */
    connectUiSounds(this);

    /** Игровые факты поля → звуковые события общей шины; отписки снимет connectLinks. */
    connectLinks({
      scene: this,
      links: [
        link(boardEvents, "next2048Merged", soundEvents, "next2048MergeSound", ({ value }) => ({
          value,
        })),
        link(boardEvents, "next2048MoveStart", soundEvents, "next2048MoveSound"),
      ],
    });
  }
}
