import { bulgePulseMotion } from "./motions/bulgePulse";
import { growFromPointMotion } from "./motions/growFromPoint";
import { pressDownMotion } from "./motions/pressDown";
import { shrinkAndFadeMotion } from "./motions/shrinkAndFade";
import { springReleaseMotion } from "./motions/springRelease";
import { squashAndSpringBackMotion } from "./motions/squashAndSpringBack";
import { stretchAlongMoveMotion } from "./motions/stretchAlongMove";

/**
 * Конечные желейные анимации — слоты JellyMotion; бесконечные — в JellyLoops.
 * Вызов — один объект, как в AnimaMover: JellyMotions.pressDown({ jelly, direction, onComplete, squashShare }).
 * Без настроек — отлаженные значения по умолчанию. Силы — доли размера (*Share), доли времени — *TimeShare.
 * Своя настройка объекта — замыкание в конфиге: (args) => JellyMotions.pressDown({ squashShare: 0.18, ...args }).
 *
 * Расширение: новая анимация — свой файл в motions/ и строка здесь. Анимации друг друга не импортируют,
 * правка одной не задевает другие; своя анимация игры — любая функция типа JellyMotion.
 */
export class JellyMotions {
  /** Рост из точки с перехлёстом, край дрожит и затихает — появление */
  static readonly growFromPoint = growFromPointMotion;
  /** Растяжение по ходу: задний край отстаёт — езда */
  static readonly stretchAlongMove = stretchAlongMoveMotion;
  /** Шлепок вдоль хода и пружина обратно — остановка после езды */
  static readonly squashAndSpringBack = squashAndSpringBackMotion;
  /** Сжатие, раздувание и растворение — поглощение */
  static readonly shrinkAndFade = shrinkAndFadeMotion;
  /** Вдавливание вдоль хода, забирает форму себе — нажатие, удар */
  static readonly pressDown = pressDownMotion;
  /** Пружина к покою и долгое колыхание края — отпускание */
  static readonly springRelease = springReleaseMotion;
  /** Разом раздувается и колышется, пружиной обратно — «хлюп» */
  static readonly bulgePulse = bulgePulseMotion;
}
