import type { IJellyMotionArgs } from "../types";

/** Настройки шлепка с пружиной. */
export interface ISquashAndSpringBackOptions {
  /** сплющивание в миг удара, доля размера; по умолчанию 0.16 */
  squashShare?: number;
  /** доля времени, за которую уходит растяжение от езды; по умолчанию 0.25 */
  stretchReleaseTimeShare?: number;
  /** пружина сплющивания: [амплитуда, период] у Elastic.Out; по умолчанию [1.1, 0.32] */
  squashSpringEase?: number[];
}

/**
 * Шлепок: в миг удара объект сплющивается вдоль оси, растяжение от езды быстро сходит,
 * затем форма пружинит обратно. Шлепок и пружина по умолчанию — 620 мс.
 */
export function squashAndSpringBackMotion(
  args: IJellyMotionArgs & ISquashAndSpringBackOptions,
): Phaser.Tweens.Tween {
  const {
    jelly,
    direction,
    durationMs = 620,
    squashShare = 0.16,
    stretchReleaseTimeShare = 0.25,
    squashSpringEase = [1.1, 0.32],
    onComplete,
  } = args;
  if (direction) jelly.setDirection(direction.x, direction.y);

  jelly.setShape({ squash: squashShare });
  jelly.animate({ stretch: 0 }, durationMs * stretchReleaseTimeShare, "Quad.Out");
  return jelly.animate({ squash: 0 }, durationMs, "Elastic.Out", {
    easeParams: [...squashSpringEase],
    onComplete,
  });
}
