import {
  AdsService,
  getUrlParam,
  isAllowedHost,
  SaveService,
  YandexDataService,
  YandexSdkWrapperV2,
} from "@kvisaz/phaser-common";
import packageInfo from "../../package.json";
import { buildConstants } from "../constants.build";
import { PlayerDataService } from "./playerData/PlayerDataService";

/** Общие сервисы игры, доступные через единственный экземпляр модуля. */
export class Services {
  /** Единая шина игры: сцены подписываются через свой SafeEventsAdapter, сервисы живут до перезагрузки страницы. */
  public readonly gameEvents = new Phaser.Events.EventEmitter();
  public readonly yandexSdkWrapperV2 = new YandexSdkWrapperV2({
    isLogging: true,
  });
  /** Сохранение игры: appId и ключ по имени пакета, как в 5 пасьянсах. */
  public readonly playerSaveService = new SaveService({
    appId: packageInfo.name,
    dataKey: `${packageInfo.name}-state`,
  });
  /** Данные игрока Next 2048 (пока настройки звука): читать getData(), менять patch(), писать flush(). */
  public readonly playerDataService = new PlayerDataService();
  public readonly adsService = new AdsService({
    isMockAd: isMockAdEnabled(),
    adCooldownMs: buildConstants.publishBuild ? 100_000 : 10_000,
  });

  /**
   * Вызывается один раз в BootScene. До завершения подготовки игровые сцены не запускаются.
   * Первым идёт SDK: от него зависят реклама и облачное сохранение.
   */
  async prepareGameServices(): Promise<void> {
    const { yandexSdkWrapperV2, adsService, playerSaveService, playerDataService } = this;
    try {
      await yandexSdkWrapperV2.init();
      const yandexPlayer = yandexSdkWrapperV2.getPlayer();
      const cloudSaveService =
        yandexPlayer != null ? new YandexDataService(yandexPlayer) : undefined;
      adsService.preload(yandexSdkWrapperV2.getSDK());
      await playerSaveService.preload(cloudSaveService);
    } catch (e) {
      console.warn(e);
    }

    /** Даже без SDK данные игрока готовы: по умолчанию, запись пойдёт в localStorage */
    playerDataService.init(playerSaveService);
  }
}

/** Моки включаются только на разрешённых хостах и по параметру ?mockAd. */
function isMockAdEnabled(): boolean {
  return isAllowedHost(["localhost", "kvisaz.github.io"]) && getUrlParam("mockAd") !== null;
}
