import { column, makeAlign, SceneEvents, setValueData } from "@kvisaz/phaser-common";
import { next2048Config } from "../config";
import { Next2048Textures } from "../shared/Next2048Textures/Next2048Textures";
import type { INext2048ScreenEvents } from "./events";
import { JellyButton } from "./JellyButton/JellyButton";
import { Next2048Board } from "./Next2048Board/Next2048Board";
import { ScoreBlock } from "./ScoreBlock/ScoreBlock";

interface INext2048ScreenProps {
  scene: Phaser.Scene;
  scoreLabel: string;
  bestLabel: string;
  /** кнопка «заново»: что делать, решает владелец — например, спросить «Вы уверены?» */
  onRestart: () => void;
  onMenu: () => void;
}

/**
 * Экран по макету: поле по центру, слева счёт и рекорд, справа три желейные кнопки.
 * Обе колонки — по центру экрана по высоте.
 */
export class Next2048Screen extends Phaser.GameObjects.Container {
  /** Поле наружу: стори и будущие сервисы (сохранение, undo-реклама) работают с ним напрямую */
  readonly board: Next2048Board;
  /** Меняющееся состояние экрана: рекорд пока живёт только до перезагрузки */
  private readonly gameState = { best: 0 };

  constructor(private props: INext2048ScreenProps) {
    super(props.scene, 0, 0);
    const { scene, scoreLabel, bestLabel, onRestart, onMenu } = this.props;
    const { scoresGap, buttonGap, scoresOffset, buttonsOffset } = next2048Config;

    this.board = new Next2048Board({ scene });
    this.add(this.board);

    const score = new ScoreBlock({
      scene,
      label: scoreLabel,
      textureKey: Next2048Textures.pillScore,
    });
    const best = new ScoreBlock({
      scene,
      label: bestLabel,
      textureKey: Next2048Textures.pillBest,
    });

    const restart = new JellyButton({ scene, icon: "restart", onClick: onRestart });
    const undo = new JellyButton({ scene, icon: "undo", onClick: () => this.board.undo() });
    const menu = new JellyButton({ scene, icon: "menu", onClick: onMenu });

    this.add([score, best, restart, undo, menu]);

    /** Колонки собираются сами, затем встают по бокам поля и по центру экрана по высоте */
    const scores = column([score, best], { nextOffsetY: scoresGap });
    const buttons = column([restart, undo, menu], { nextOffsetY: buttonGap });

    makeAlign((align) => {
      align.anchorSceneScreen(scene).center(this.board);
      align.anchor(this.board).leftTo(scores, -scoresOffset).rightTo(buttons, buttonsOffset);
      align.anchorSceneScreen(scene).centerY(scores).centerY(buttons);
    });

    /** Счёт и рекорд — по событию поля */
    const { gameState } = this;
    const events = new SceneEvents<INext2048ScreenEvents>({ scene, autoUnSub: this });
    events.on("next2048Score", ({ score: value }) => {
      gameState.best = Math.max(gameState.best, value);
      setValueData(score, value);
      setValueData(best, gameState.best);
    });
  }
}
