import {
  createTileMergePolicy,
  createTileSpawnPolicy,
  Game2048GridModel,
} from "@kvisaz/phaser-common";
import { next2048Config } from "../../config";
import type { INext2048Model } from "./types";

/** Модель 2048 из phaser-common под контрактом поля: единственное место, где поле зависит от библиотеки. */
export function createNext2048Model(): INext2048Model {
  const { gridSize, startStageValue, maxTileValue, winValue } = next2048Config;

  return new Game2048GridModel({
    size: gridSize,
    tileMergePolicy: createTileMergePolicy({ maxTileValue }),
    tileSpawnPolicy: createTileSpawnPolicy({
      game2048Config: { startStageValue, maxTileValue, winValue },
    }),
  });
}
