import {
  InputBlocker,
  makeAlign,
  SafeEventsAdapter,
  UnSubManager,
  type AdsService,
} from "@kvisaz/phaser-common";
import type { IGameAdEvents } from "./events";

interface IGameAdsServiceProps {
  scene: Phaser.Scene;
  events: Phaser.Events.EventEmitter;
  ads: AdsService;
}

type FullscreenContinue = "game2048NewGameRequest" | "game2048ContinueRequest";

/** Пары «клик игрока → действие после рекламы». */
const fullscreenFlows: ReadonlyArray<{ request: "game2048NewGameClick" | "game2048ContinueClick"; next: FullscreenContinue }> = [
  { request: "game2048NewGameClick", next: "game2048NewGameRequest" },
  { request: "game2048ContinueClick", next: "game2048ContinueRequest" },
];

/** Единый рекламный flow приложения: один показ, временный mute и результат через события. */
export class GameAdsService {
  private readonly unSubs = new UnSubManager();
  private readonly events: SafeEventsAdapter<IGameAdEvents>;
  private readonly continuations = new Set<FullscreenContinue>();
  private busy = false;
  private inputBlocker?: InputBlocker;
  private destroyed = false;

  /** Подключает запросы до создания первого экрана. */
  constructor(private readonly props: IGameAdsServiceProps) {
    const events = (this.events = new SafeEventsAdapter<IGameAdEvents>(props.events));
    this.unSubs.addUnSub(() => events.unSubscribeAll());

    fullscreenFlows.forEach(({ request, next }) => events.on(request, () => this.fullscreen(next)));
    events.on("requestRewardAd", ({ rewardType }) => this.rewarded(rewardType));
  }

  /** Продолжает действие и без показа; повторный запрос ждёт закрытия текущей рекламы. */
  private fullscreen(next: FullscreenContinue): void {
    const { ads } = this.props;
    const { events } = this;
    if (!this.busy && !ads.isFullAdEnabled) {
      events.emit(next);
      return;
    }
    this.continuations.add(next);
    if (this.busy) return;
    this.start();
    ads.showCommonAd(() => this.finish());
  }

  /** Возвращает результат награды событием; без SDK или во время другой рекламы — «не показана». */
  private rewarded(rewardType: string): void {
    const { ads } = this.props;
    const { events } = this;
    if (this.busy || !ads.isRewardAdEnabled) {
      events.emit("onRewardAdClosed", {
        rewardType,
        wasShown: false,
        error: this.busy ? "ad flow is busy" : "rewarded ad is unavailable",
      });
      return;
    }
    this.start();
    ads.showRewardedAd((result) => {
      if (this.destroyed) return;
      try {
        events.emit("onRewardAdClosed", { rewardType, wasShown: result.wasShown, error: result.error });
      } finally {
        this.finish();
      }
    });
  }

  /** Блокирует ввод до обращения к SDK и временно выключает звук. */
  private start(): void {
    const { scene } = this.props;
    this.busy = true;
    scene.scene.bringToTop();
    const inputBlocker = (this.inputBlocker = new InputBlocker({ scene }));
    makeAlign((align) => align.anchorSceneScreen(scene).center(inputBlocker));
    scene.add.existing(inputBlocker);
    this.events.emit("coreSoundMuteRequest", { owner: "ads", muted: true });
  }

  /** Отправляет продолжения и снимает рекламный mute. */
  private finish(): void {
    if (this.destroyed || !this.busy) return;
    this.inputBlocker?.destroy();
    this.inputBlocker = undefined;
    this.busy = false;
    const pending = [...this.continuations];
    this.continuations.clear();
    try {
      pending.forEach((next) => this.events.emit(next));
    } finally {
      this.events.emit("coreSoundMuteRequest", { owner: "ads", muted: false });
    }
  }

  /** Поздние ответы SDK не обращаются к закрытому приложению. */
  destroy(): void {
    this.destroyed = true;
    this.inputBlocker?.destroy();
    this.inputBlocker = undefined;
    this.unSubs.destroy();
    this.continuations.clear();
    if (this.busy) this.events.emit("coreSoundMuteRequest", { owner: "ads", muted: false });
    this.busy = false;
  }
}
