import { SCENES } from "../../scenes";
import { Next2048Textures } from "../Next2048Scene/shared/Next2048Textures/Next2048Textures";
import { preloadBoot, setupGameLocale } from "./setupBoot";
import { services } from "../../services";

/** Загружает общие ассеты игры перед запуском основной сцены. */
export class BootScene extends Phaser.Scene {
  /** Создает Boot-сцену для одноразовой загрузки ассетов. */
  constructor() {
    super(SCENES.boot);
  }

  preload(): void {
    /** сервисы, ассеты, все что надо предзагрузить - компактно пиши в preloadBoot **/
    preloadBoot(this);
  }

  /** Запускает основную игровую сцену после завершения preload. */
  create(): void {
    setupGameLocale();
    /** Текстуры нового дизайна — один раз на игру, шрифт уже загружен в preload */
    Next2048Textures.generate(this);
    /** Постоянные сервисы запускаются раньше игрового экрана. */
    this.scene.launch(SCENES.services);
    this.scene.start(SCENES.next2048);
    services.yandexSdkWrapperV2.signalGameReady();
  }
}
