import type { ILivelyProfile } from "../livelyWaves";
import type { IJellyLoop } from "../../shared/types";
import type { IJellyLoopArgs } from "../types";

/**
 * Живая рябь края в покое — у каждого объекта свой узор (JellyMesh.startIdle).
 * Не заданные поля профиля — спокойная рябь по умолчанию: край 0.4–1.2 px, смена силы 1.5–4.5 с,
 * 3–6 гребней, обход контура 20–70 с, жизнь узора 2–6 с.
 * stop() — рябь пропадает, край возвращается в покой.
 */
export function loopEdgeRipple(args: IJellyLoopArgs & Partial<ILivelyProfile>): IJellyLoop {
  const { jelly, ...profileOptions } = args;

  jelly.startIdle({
    edgeOffsetMaxPx: 1.2,
    edgeOffsetMinPx: 0.4,
    calmChangeMinMs: 1500,
    calmChangeMaxMs: 4500,
    crestCountMin: 3,
    crestCountMax: 6,
    crestLapMinSec: 20,
    crestLapMaxSec: 70,
    waveLifeMinMs: 2000,
    waveLifeMaxMs: 6000,
    ...profileOptions,
  });

  return { kind: "loop", stop: () => jelly.stopIdle() };
}
