import {
  JellyLoops,
  JellyMotions,
  type JellyLoopStart,
  type JellyMotion,
} from "../../../../../common/animation/animation-jelly";

/**
 * Движение желейной плитки: езда, появление, шлепок, слияние, поглощение и живая рябь.
 * Желе — слоты двух родов, род проверяет компилятор (satisfies):
 * - `<событие>Animation` — конечная анимация JellyMotions (satisfies JellyMotion);
 * - `<событие>Loop` — бесконечная JellyLoops, останавливается через stop() (satisfies JellyLoopStart).
 * Стратегия как есть — отлаженные значения по умолчанию (видны в подсказке настроек);
 * своё у плитки — замыкание: (args) => JellyMotions.pressDown({ squashShare: 0.18, ...args }).
 * Время езды — игровое, moveMs в next2048Config: столько же ждёт вторая фаза хода.
 */
export const jellyTileMotion = {
  /** растяжение по ходу во время езды; длительность при игре — moveMs */
  moveAnimation: JellyMotions.stretchAlongMove satisfies JellyMotion,
  /** новая плитка появилась */
  spawnAnimation: JellyMotions.growFromPoint satisfies JellyMotion,
  /** плитка доехала и остановилась: шлепок и пружина */
  landAnimation: JellyMotions.squashAndSpringBack satisfies JellyMotion,
  /** удар соседа при слиянии: вдавливается слабее кнопки; в пике меняется номинал */
  mergePressAnimation: ((args) =>
    JellyMotions.pressDown({ squashShare: 0.176, bulgeShare: 0.014, ...args })) satisfies JellyMotion,
  /** пружина и колыхание после удара — как у отпущенной кнопки */
  mergeReleaseAnimation: JellyMotions.springRelease satisfies JellyMotion,
  /** поглощённая плитка тает под соседом */
  absorbAnimation: JellyMotions.shrinkAndFade satisfies JellyMotion,

  /** Живая рябь края плитки: заметная и быстрая — край «кипит»; плитка 184 px */
  idleLoop: ((args) =>
    JellyLoops.loopEdgeRipple({
      /** край в самый бурный момент отходит от покоя на столько, px; углы — примерно в √2 раза дальше */
      edgeOffsetMaxPx: 3,
      /** край в самый тихий момент, px */
      edgeOffsetMinPx: 2,
      /** сила ряби всё время плавно едет к новой случайной цели между min и max px; один такой переезд длится, мс */
      calmChangeMinMs: 1200,
      calmChangeMaxMs: 3500,
      /** гребней волны по контуру, целое */
      crestCountMin: 1,
      crestCountMax: 6,
      /** гребень обходит контур за столько секунд */
      crestLapMinSec: 12,
      crestLapMaxSec: 25,
      /** узор одной волны рождается и гаснет за столько мс */
      waveLifeMinMs: 1500,
      waveLifeMaxMs: 4500,
      ...args,
    })) satisfies JellyLoopStart,
};
