import {
  explodeParticles,
  grid,
  makeAlign,
  makeView,
  SceneEvents,
  UnSubManager,
} from "@kvisaz/phaser-common";
import { JellyOutline } from "../../../../common/animation/animation-jelly";
import { next2048Config } from "../../config";
import { addBoardInput } from "./addBoardInput";
import { boardMotion } from "./boardMotion";
import { Next2048Textures } from "../../shared/Next2048Textures/Next2048Textures";
import { createNext2048Model } from "./createNext2048Model";
import type { INext2048BoardEvents } from "./events";
import { JellyTile } from "./JellyTile/JellyTile";
import type {
  BoardDirection,
  INext2048MergeEvent,
  INext2048Model,
  INext2048Snapshot,
} from "./types";

interface INext2048BoardProps {
  scene: Phaser.Scene;
}

/** Меняющееся состояние поля: плитки на поле, анимация хода, очередь и отмена. */
interface IBoardGameState {
  tiles: Map<number, JellyTile>;
  /** идёт анимация хода: следующий ход ждёт в очереди, а не теряется */
  busy: boolean;
  queued?: BoardDirection;
  moveTimer?: Phaser.Time.TimerEvent;
  /** снимок до последнего хода: одна отмена */
  undoSnapshot?: INext2048Snapshot;
}

/**
 * Игровое поле Next 2048: модель 2048 по контракту INext2048Model, желейные плитки и живая рамка.
 * Без сервисов и UI: наружу — методы хода и партии и события INext2048BoardEvents.
 */
export class Next2048Board extends Phaser.GameObjects.Container {
  private readonly unSubs = new UnSubManager();
  private readonly events: SceneEvents<INext2048BoardEvents>;
  private readonly model: INext2048Model;
  /** Пустые клетки [row][col]: по ним стоят плитки, поглощённые опускаются сразу над ними */
  private readonly slots: Phaser.GameObjects.Image[][];
  /** Живая рамка поля */
  private readonly border: JellyOutline;
  private readonly gameState: IBoardGameState = { tiles: new Map(), busy: false };

  constructor(private props: INext2048BoardProps) {
    super(props.scene, 0, 0);
    const { scene } = this.props;
    const { gridSize, cellSize, cellGap } = next2048Config;
    const side = getBoardSide();

    this.events = new SceneEvents<INext2048BoardEvents>({ scene, autoUnSub: this });
    this.model = createNext2048Model();

    /** Невидимая зона задаёт границы поля для раскладки: Mesh и Rope в getBounds контейнера не входят */
    const area = new Phaser.GameObjects.Zone(scene, 0, 0, side, side);
    this.add(area);

    this.slots = Array.from({ length: gridSize }, () =>
      Array.from({ length: gridSize }, () =>
        makeView(scene, (b) => b.img({ textureName: Next2048Textures.slot })),
      ),
    );
    this.add(this.slots.flat());

    this.border = new JellyOutline({
      scene,
      width: side,
      height: side,
      cornerRadius: next2048Config.boardRadius,
      lineTextureKey: Next2048Textures.line,
    });
    this.add(this.border);
    boardMotion.idleLoop({ outline: this.border });

    /** Клетки — сеткой с шагом клетка + зазор, сетка — по центру поля */
    makeAlign((align) => {
      const cells = grid(this.slots, {
        cellAutoDetect: false,
        cellWidth: cellSize + cellGap,
        cellHeight: cellSize + cellGap,
      });
      align.anchor(area).center(cells);
    });

    this.renderTiles();

    this.unSubs.addUnSub(addBoardInput({ scene, onMove: (direction) => this.move(direction) }));
  }

  /** Снимает ввод и таймер хода; плитки и рамка уничтожаются вместе с детьми. */
  destroy(fromScene?: boolean) {
    this.unSubs.destroy();
    this.gameState.moveTimer?.remove();
    super.destroy(fromScene);
  }

  /** Ход по направлению: ввод, кнопки и бот вызывают одно и то же. Во время анимации ход ставится в очередь. */
  move(direction: BoardDirection) {
    const { model, gameState } = this;
    if (gameState.busy) {
      gameState.queued = direction;
      return;
    }

    const { tiles } = gameState;
    const { dx, dy } = directionVectors[direction];
    const before = model.createHistorySnapshot();
    const result = model.move(direction);
    if (!result.moved) {
      this.bumpBorder(dx, dy);
      this.events.emit("next2048Blocked");
      return;
    }
    this.events.emit("next2048MoveStart");
    gameState.busy = true;
    gameState.undoSnapshot = before;

    /** Плитки, которых нет в модели после хода, — поглощённые: доезжают и тают под соседом */
    const alive = new Set<number>();
    model.forEachTile((tile) => alive.add(tile.id));
    /** Выжившей плитке в клетке слияния шлепок не нужен: форму у цели задаст слияние */
    const mergeCells = new Set(result.mergeEvents.map(({ row, col }) => `${row}:${col}`));
    const lastSlot = this.slots[this.slots.length - 1][this.slots.length - 1];

    for (const { tileId, toRow, toCol } of result.tileMotions) {
      const tile = tiles.get(tileId);
      if (!tile) continue;

      const { x, y } = this.slots[toRow][toCol];
      if (alive.has(tileId)) {
        tile.playMove(x, y, dx, dy, !mergeCells.has(`${toRow}:${toCol}`));
        continue;
      }

      tiles.delete(tileId);
      this.moveAbove<Phaser.GameObjects.GameObject>(tile, lastSlot);
      tile.playMove(x, y, dx, dy, false, () => tile.playAbsorb(() => tile.destroy()));
    }

    /** Вторая фаза — когда плитки доехали: время езды — игровое moveMs */
    gameState.moveTimer = this.scene.time.delayedCall(next2048Config.moveMs, () =>
      this.finishMove(result.scoreGained, result.mergeEvents, dx, dy),
    );
  }

  /** Новая партия без пересоздания поля. */
  newGame() {
    this.gameState.undoSnapshot = undefined;
    this.model.reset();
    this.renderTiles();
  }

  /** Отменяет последний ход: поле возвращается к снимку до него. */
  undo() {
    const { busy, undoSnapshot } = this.gameState;
    if (busy || !undoSnapshot) return;

    this.restoreSnapshot(undoSnapshot);
  }

  /** Снимок партии для сохранения и undo. */
  getSnapshot(): INext2048Snapshot {
    return this.model.createHistorySnapshot();
  }

  /** Восстанавливает партию из снимка: плитки появляются заново, отменять больше нечего. */
  restoreSnapshot(snapshot: INext2048Snapshot) {
    this.gameState.undoSnapshot = undefined;
    this.model.restoreHistorySnapshot(snapshot);
    this.renderTiles();
  }

  /** Вторая фаза хода: слияния, новая плитка, события; затем ход из очереди. */
  private finishMove(gained: number, mergeEvents: INext2048MergeEvent[], dx: number, dy: number) {
    const { model, events, gameState } = this;
    const { tiles } = gameState;

    for (const { row, col, value } of mergeEvents) {
      const survivor = model.getTile(row, col);
      const tile = survivor && tiles.get(survivor.id);
      if (!tile) continue;

      tile.playMerge(value, dx, dy);
      this.playMergeEffects(tile, value);
      const world = this.toWorld(tile.x, tile.y);
      events.emit("next2048Merged", { value, x: world.x, y: world.y });
    }

    const spawned = model.addRandomTile("move");
    if (spawned) {
      this.createTile(spawned.id, spawned.value, spawned.row, spawned.col).playSpawn();
      events.emit("next2048Spawned", { value: spawned.value });
    }

    events.emit("next2048Moved", { score: model.score, gained });
    events.emit("next2048Score", { score: model.score });
    if (!model.canMove()) events.emit("next2048NoMoves");

    gameState.busy = false;
    const { queued } = gameState;
    gameState.queued = undefined;
    if (queued) this.move(queued);
  }

  /** Капли цвета плитки разлетаются, по рамке бежит волна от ближайшего края. */
  private playMergeEffects(tile: JellyTile, value: number) {
    const { scene } = this.props;
    const { body, outline } = Next2048Textures.tileColors(value);
    const world = this.toWorld(tile.x, tile.y);

    explodeParticles({
      scene,
      x: world.x,
      y: world.y,
      count: boardMotion.dropsCount,
      colors: [body, outline],
      shape: "circle",
      size: { start: boardMotion.dropsSizeStart, end: boardMotion.dropsSizeEnd },
      ease: "Quad.Out",
      speed: { min: boardMotion.dropsSpeedMin, max: boardMotion.dropsSpeedMax },
      lifespan: { min: boardMotion.dropsLifeMinMs, max: boardMotion.dropsLifeMaxMs },
      gravityY: 0,
      blendMode: Phaser.BlendModes.NORMAL,
    });

    boardMotion.mergeImpactAnimation({ outline: this.border, x: tile.x, y: tile.y });
  }

  /** Ход в стену: рамка вздрагивает с той стороны, куда толкнули. */
  private bumpBorder(dx: number, dy: number) {
    const half = getBoardSide() / 2;
    boardMotion.wallImpactAnimation({ outline: this.border, x: dx * half, y: dy * half });
  }

  /** Пересобирает плитки по модели: каждая появляется с анимацией; счёт сообщается заново. */
  private renderTiles() {
    const { gameState, model } = this;
    gameState.tiles.forEach((tile) => tile.destroy());
    gameState.tiles.clear();
    gameState.moveTimer?.remove();
    gameState.busy = false;
    gameState.queued = undefined;

    model.forEachTile(({ id, value, row, col }) =>
      this.createTile(id, value, row, col).playSpawn(),
    );
    this.events.emit("next2048Score", { score: model.score });
  }

  /** Плитка встаёт в центр своей клетки. */
  private createTile(id: number, value: number, row: number, col: number): JellyTile {
    const { scene } = this.props;
    const { x, y } = this.slots[row][col];
    const tile = new JellyTile({ scene, value, x, y });
    /**
     * Плитки — прямо в поле под рамкой: раздутый край не закрывает линию.
     * Не отдельным слоем: Mesh не даёт getBounds, и слой из одних плиток сбивает границы поля в (0, 0).
     */
    this.addAt(tile, this.getIndex(this.border));
    this.gameState.tiles.set(id, tile);
    return tile;
  }

  private toWorld(x: number, y: number): Phaser.Types.Math.Vector2Like {
    return this.getWorldTransformMatrix().transformPoint(x, y, new Phaser.Math.Vector2());
  }
}

/** Направление хода → единичный вектор на экране (y вниз). */
const directionVectors: Record<BoardDirection, { dx: number; dy: number }> = {
  up: { dx: 0, dy: -1 },
  down: { dx: 0, dy: 1 },
  left: { dx: -1, dy: 0 },
  right: { dx: 1, dy: 0 },
};

/** Сторона поля: клетки, зазоры между ними и поля по краям. */
function getBoardSide(): number {
  const { gridSize, cellSize, cellGap, boardPadding } = next2048Config;
  return gridSize * cellSize + (gridSize - 1) * cellGap + boardPadding * 2;
}
