import type { IJellyMotionArgs } from "../types";

/** Настройки сжатия с растворением. */
export interface IShrinkAndFadeOptions {
  /** до какого масштаба сжимается объект; по умолчанию 0.55 */
  shrinkTo?: number;
  /** раздувание сторон, пока объект тает, доля размера; по умолчанию 0.084 */
  bulgeShare?: number;
}

/**
 * Сжатие с растворением: объект влипает в соседа — сжимается, раздувается и прозрачнеет до 0, по умолчанию за 140 мс.
 * Возвращает tween прозрачности; onComplete — когда объект растаял и его можно уничтожать.
 */
export function shrinkAndFadeMotion(args: IJellyMotionArgs & IShrinkAndFadeOptions): Phaser.Tweens.Tween {
  const { jelly, durationMs = 140, shrinkTo = 0.55, bulgeShare = 0.084, onComplete } = args;

  jelly.animate({ grow: shrinkTo, bulge: bulgeShare }, durationMs, "Quad.In");
  return jelly.scene.tweens.add({
    targets: jelly,
    alpha: 0,
    duration: durationMs,
    ease: "Quad.In",
    onComplete: () => onComplete?.(),
  });
}
