import type { IJellyMotionArgs } from "../types";

/** Настройки «хлюпа». */
export interface IBulgePulseOptions {
  /** раздувание в начале, доля размера; по умолчанию 0.126 */
  bulgeShare?: number;
  /** колыхание края в начале, доля радиуса; по умолчанию 0.056 */
  edgeWaveShare?: number;
  /** пружина раздувания: [амплитуда, период] у Elastic.Out; по умолчанию [1.2, 0.4] */
  bulgeSpringEase?: number[];
  /** на сколько радиан пробегают волны края, пока колыхание затихает; по умолчанию 10 */
  edgeWavePhase?: number;
}

/** «Хлюп»: объект разом раздувается и колышется, затем пружиной возвращается к покою; по умолчанию 600 мс. */
export function bulgePulseMotion(args: IJellyMotionArgs & IBulgePulseOptions): Phaser.Tweens.Tween {
  const {
    jelly,
    durationMs = 600,
    bulgeShare = 0.126,
    edgeWaveShare = 0.056,
    bulgeSpringEase = [1.2, 0.4],
    edgeWavePhase = 10,
    onComplete,
  } = args;

  jelly.setShape({ bulge: bulgeShare, wobble: edgeWaveShare });
  jelly.animate({ bulge: 0 }, durationMs, "Elastic.Out", { easeParams: [...bulgeSpringEase] });
  return jelly.animate(
    { wobble: 0, phase: jelly.shape.phase + edgeWavePhase },
    durationMs,
    "Sine.Out",
    { onComplete },
  );
}
