import {
  JellyLoops,
  JellyMotions,
  type JellyLoopStart,
  type JellyMotion,
} from "../../../common/animation/animation-jelly";

/** Слоты анимаций желейной кнопки: наведение, нажатие, отпускание. */
export interface IJellyButtonMotion {
  /** указатель над кнопкой: край колышется, пока указатель не уйдёт; stop() — колыхание гаснет */
  hoverLoop: JellyLoopStart;
  /** нажатие: кнопка вдавливается */
  pressAnimation: JellyMotion;
  /** отпускание: пружинит и колышется */
  releaseAnimation: JellyMotion;
}

/**
 * Анимации желейной кнопки по умолчанию — отлаженные значения JellyMotions и JellyLoops, под круглую кнопку 162 px.
 * Кнопке другой формы нужны свои значения: addJellyButtonBehavior принимает их в props.motion поверх этих.
 */
export const jellyButtonMotion = {
  hoverLoop: JellyLoops.loopEdgeWave,
  pressAnimation: JellyMotions.pressDown,
  releaseAnimation: JellyMotions.springRelease,
} satisfies IJellyButtonMotion;
