import { makeAlign, makeView, row } from "@kvisaz/phaser-common";
import { Next2048Textures } from "../../../Next2048Scene/shared/Next2048Textures/Next2048Textures";
import { nextUiConfig, type NextUiAccent } from "../config";
import { NextUiButton } from "../NextUiButton/NextUiButton";
import { NextUiTextures } from "../NextUiTextures";
import { NextUiToggleRow } from "../NextUiToggleRow/NextUiToggleRow";
import type { INextDialogViewAction, INextDialogViewToggle } from "./types";

interface INextDialogViewProps {
  scene: Phaser.Scene;
  accent: NextUiAccent;
  title: string;
  /** текст под вставкой: готовая строка, переносы — по ширине окошка */
  message?: string;
  /** плитка этого номинала над сообщением, например победная 2048 */
  tileValue?: number;
  /** строки настроек над сообщением */
  toggles?: INextDialogViewToggle[];
  actions: INextDialogViewAction[];
}

/**
 * Вид диалога: цветная рамка-плитка с заголовком в шапке и светлым окошком, где сверху вниз идут
 * вставка (плитка или строки настроек), сообщение и кнопки. Высота панели считается по содержимому.
 * Без логики: что делают кнопки, решает вызывающий. Показывает его openNextDialog или сторис.
 */
export class NextDialogView extends Phaser.GameObjects.Container {
  constructor(private props: INextDialogViewProps) {
    super(props.scene, 0, 0);
    const { scene, accent, title, message, tileValue, toggles = [], actions } = this.props;
    const {
      texturePad,
      panelWidth,
      panelHeader,
      panelInset,
      titleFontSize,
      messageFontSize,
      messageColor,
      messageWidth,
      dialogGap,
      buttonGap,
      tileButtonHeight,
      fontFamily,
      textColor,
    } = nextUiConfig;

    const titleText = makeView(scene, (b) =>
      b.text({
        text: title,
        style: { fontFamily, fontSize: `${titleFontSize}px`, color: textColor },
      }),
    );

    /** Части окошка сверху вниз: вставка, строки настроек, сообщение */
    const tileImage =
      tileValue != null
        ? makeView(scene, (b) => b.img({ textureName: Next2048Textures.tile(tileValue) }))
        : undefined;
    const toggleRows = toggles.map((item) => new NextUiToggleRow({ scene, ...item }));
    const messageText =
      message != null
        ? makeView(scene, (b) =>
            b.text({
              text: message,
              style: {
                fontFamily,
                fontSize: `${messageFontSize}px`,
                color: messageColor,
                align: "center",
                wordWrap: { width: messageWidth },
              },
            }),
          )
        : undefined;
    const parts = [tileImage, ...toggleRows, messageText].filter((part) => part != null);

    const buttons = actions.map(
      ({ label, tone, onClick }) => new NextUiButton({ scene, look: "tile", tone, label, onClick }),
    );

    /** Высота панели по содержимому: шапка, части с отступами, кнопки и поля снизу */
    const partsHeight = parts.reduce((sum, part) => sum + part.getBounds().height + dialogGap, 0);
    const panelHeight =
      panelHeader + dialogGap + partsHeight + tileButtonHeight + dialogGap + panelInset;
    const panel = makeView(scene, (b) =>
      b.img({
        textureName: NextUiTextures.panel(scene, {
          accent,
          width: panelWidth,
          height: panelHeight,
        }),
      }),
    );

    this.add([panel, titleText, ...parts, ...buttons]);

    makeAlign((align) => {
      /** Заголовок по центру шапки */
      align
        .anchor(panel)
        .centerX(titleText)
        .topIn(titleText, texturePad + (panelHeader - titleText.getBounds().height) / 2);

      /** Части и кнопки — цепочкой друг под другом по центру */
      const firstTop = texturePad + panelHeader + dialogGap;
      parts.forEach((part, index) => {
        if (index === 0) {
          align.anchor(panel).centerX(part).topIn(part, firstTop);
        } else {
          align
            .anchor(parts[index - 1])
            .centerX(part)
            .bottomTo(part, dialogGap);
        }
      });

      const buttonsRow = row(buttons, { nextOffsetX: buttonGap });
      const lastPart = parts[parts.length - 1];
      if (lastPart) {
        align.anchor(lastPart).centerX(buttonsRow).bottomTo(buttonsRow, dialogGap);
      } else {
        align.anchor(panel).centerX(buttonsRow).topIn(buttonsRow, firstTop);
      }
    });
  }
}
