import { JellyLoops, JellyMesh } from "../../../../common/animation/animation-jelly";
import { addJellyButtonBehavior } from "../../jelly-button/addJellyButtonBehavior";
import { nextUiConfig } from "../config";
import { NextUiTextures } from "../NextUiTextures";
import { nextUiMotion } from "../nextUiMotion";

interface INextUiToggleProps {
  scene: Phaser.Scene;
  /** начальное состояние */
  on: boolean;
  /** новое состояние после нажатия и отпускания над переключателем */
  onChange: (on: boolean) => void;
}

/**
 * Желейный переключатель настроек: дорожка и ручка — желе, как у кнопок.
 * Дорожка вдавливается и пружинит от нажатия; ручка перетекает как капля: тянется по ходу,
 * у края шлёпается и колышется, а цвет дорожки меняется на полпути.
 * Звук нажатия шлёт makeButton: нужен мост connectUiSounds(scene) в сцене переключателя.
 */
export class NextUiToggle extends Phaser.GameObjects.Container {
  private readonly track: JellyMesh;
  private readonly knob: JellyMesh;
  /** Меняющееся состояние: включён ли переключатель */
  private readonly gameState: { on: boolean };

  constructor(private props: INextUiToggleProps) {
    super(props.scene, 0, 0);
    const { scene, on } = this.props;
    const { texturePad, toggleWidth, toggleHeight, toggleKnobSize, toggleKnobTravel } =
      nextUiConfig;
    this.gameState = { on };

    /** Зона задаёт размер и область нажатия: у Mesh нет getBounds */
    this.add(new Phaser.GameObjects.Zone(scene, 0, 0, toggleWidth, toggleHeight));

    this.track = new JellyMesh({
      scene,
      x: 0,
      y: 0,
      textureKey: NextUiTextures.toggleTrack(scene, on),
      width: toggleWidth + texturePad * 2,
      height: toggleHeight + texturePad * 2,
    });
    this.knob = new JellyMesh({
      scene,
      x: on ? toggleKnobTravel : -toggleKnobTravel,
      y: 0,
      textureKey: NextUiTextures.toggleKnob(scene),
      width: toggleKnobSize + texturePad * 2,
      height: toggleKnobSize + texturePad * 2,
    });
    this.add([this.track, this.knob]);

    /** Живая рябь: у широкой дорожки спокойная, как у капсулы, у ручки — как у круглой кнопки */
    nextUiMotion.wideIdleLoop({ jelly: this.track });
    JellyLoops.loopEdgeRipple({ jelly: this.knob });

    this.setName("next-ui-toggle");
    addJellyButtonBehavior({
      obj: this,
      jelly: this.track,
      motion: nextUiMotion.toggleTrack,
      clickOn: "release",
      onClick: () => this.toggle(),
    });
  }

  /** Снимает tween езды ручки; Mesh-и снимают свои tween-ы формы сами. */
  destroy(fromScene?: boolean) {
    this.props.scene.tweens?.killTweensOf(this.knob);
    super.destroy(fromScene);
  }

  /**
   * Переключает состояние. Ручка едет как плитка поля, но мягче: тянется по ходу (инерция), у края шлёпается
   * и пружинит; слоты — nextUiMotion.toggleKnob. Цвет дорожки меняется ровно на полпути езды.
   */
  private toggle() {
    const { scene, onChange } = this.props;
    const { gameState, track, knob } = this;
    const { toggleKnobTravel } = nextUiConfig;
    const { moveMs, moveAnimation, landAnimation } = nextUiMotion.toggleKnob;
    gameState.on = !gameState.on;
    const direction = { x: gameState.on ? 1 : -1, y: 0 };

    /** Прежняя езда обрывается без шлепка: новый ход забирает ручку себе */
    scene.tweens.killTweensOf(knob);
    moveAnimation({ jelly: knob, direction, durationMs: moveMs });
    scene.tweens.add({
      targets: knob,
      x: gameState.on ? toggleKnobTravel : -toggleKnobTravel,
      duration: moveMs,
      ease: "Quad.In",
      onComplete: () => landAnimation({ jelly: knob, direction }),
    });

    /** Цвет берётся из состояния на момент смены: быстрые нажатия подряд не рассинхронят дорожку */
    scene.time.delayedCall(moveMs / 2, () => {
      if (track.active) track.setTexture(NextUiTextures.toggleTrack(scene, gameState.on));
    });

    onChange(gameState.on);
  }
}
