import {
  JellyOutlineLoops,
  JellyOutlineMotions,
  type JellyOutlineLoopStart,
  type JellyOutlineMotion,
} from "../../../../common/animation/animation-jelly";

/**
 * Движение поля: живая рамка JellyOutline (приливы покоя и волны удара) и капли при слиянии.
 * Слоты рамки проверяет компилятор (satisfies); своё у поля — замыкание: (args) => JellyOutlineMotions.impactRipple({ heightPx: 9, ...args }).
 */
export const boardMotion = {
  /** приливы покоя: два горба на противоположных краях медленно едут по кругу */
  idleLoop: JellyOutlineLoops.loopTides satisfies JellyOutlineLoopStart,
  /** волна от слияния плиток — высота по умолчанию, 14 px */
  mergeImpactAnimation: JellyOutlineMotions.impactRipple satisfies JellyOutlineMotion,
  /** волна от хода в стену — пониже */
  wallImpactAnimation: ((args) =>
    JellyOutlineMotions.impactRipple({ heightPx: 9, ...args })) satisfies JellyOutlineMotion,

  /** число капель цвета плитки при слиянии */
  dropsCount: 16,
  /** радиус капли в начале и в конце жизни, px */
  dropsSizeStart: 15,
  dropsSizeEnd: 2,
  /** скорость разлёта капель, px/с */
  dropsSpeedMin: 140,
  dropsSpeedMax: 340,
  /** жизнь капли, мс */
  dropsLifeMinMs: 420,
  dropsLifeMaxMs: 720,
};
