import type { IJellyMotionArgs } from "../types";

/** Настройки растяжения по ходу. */
export interface IStretchAlongMoveOptions {
  /** растяжение в конце, доля размера; по умолчанию 0.22 */
  stretchShare?: number;
}

/**
 * Растяжение по ходу: задний край отстаёт, как у желе с инерцией. Набирается по умолчанию за 130 мс —
 * обычно столько же длится езда, поэтому её время лучше передать в durationMs.
 * Прежние анимации формы не снимает; убрать растяжение — следующей анимацией (например, squashAndSpringBack).
 */
export function stretchAlongMoveMotion(
  args: IJellyMotionArgs & IStretchAlongMoveOptions,
): Phaser.Tweens.Tween {
  const { jelly, direction, durationMs = 130, stretchShare = 0.22, onComplete } = args;
  if (direction) jelly.setDirection(direction.x, direction.y);

  return jelly.animate({ stretch: stretchShare }, durationMs, "Quad.Out", { onComplete });
}
