import {
  blobPath,
  fillSoft,
  softRectPath,
  strokeSoft,
  toRgba,
} from "../../../common/canvas/canvas";
import { nextUiConfig, type NextUiAccent, type NextUiTone } from "./config";

/** Значок строки настроек. */
export type NextUiRowIcon = "speaker" | "note";

export interface ITileButtonOptions {
  tone: NextUiTone;
  /** размер кнопки без каймы текстуры */
  width: number;
  height: number;
}

export interface IPanelOptions {
  accent: NextUiAccent;
  /** размер панели без каймы текстуры */
  width: number;
  height: number;
}

/** Кнопка-плитка: тот же рецепт, что у drawTileTexture — тело, мягкая «подушка», обводка, — но прямоугольная. */
export function drawTileButtonTexture(ctx: CanvasRenderingContext2D, options: ITileButtonOptions) {
  const { tone, width, height } = options;
  const { texturePad: pad, tileButtonInset: inset, tones, tileRadius } = nextUiConfig;
  const { body, inner, outline } = tones[tone];
  const bulge = 1.5;

  /** Тело */
  softRectPath(ctx, pad, pad, width, height, tileRadius, bulge);
  ctx.fillStyle = toRgba(body);
  ctx.fill();

  /** «Подушка»: внутренний прямоугольник темнее с размытым краем */
  fillSoft(ctx, inner, 4, (dx) =>
    softRectPath(
      ctx,
      pad + inset + dx,
      pad + inset,
      width - inset * 2,
      height - inset * 2,
      tileRadius * 0.75,
      bulge * 0.6,
    ),
  );

  /** Обводка поверх тела */
  softRectPath(ctx, pad, pad, width, height, tileRadius, bulge);
  strokeSoft(ctx, outline, 3);
}

/** Панель диалога: цветная рамка-плитка с «подушкой» и светлое окошко под шапкой. */
export function drawPanelTexture(ctx: CanvasRenderingContext2D, options: IPanelOptions) {
  const { accent, width, height } = options;
  const {
    texturePad: pad,
    panelRadius,
    panelHeader,
    panelInset,
    cardRadius,
    cardColor,
    accents,
  } = nextUiConfig;
  const { body, inner, outline } = accents[accent];
  const bulge = 1.6;

  /** Тело рамки */
  softRectPath(ctx, pad, pad, width, height, panelRadius, bulge);
  ctx.fillStyle = toRgba(body);
  ctx.fill();

  /** «Подушка» рамки */
  const cushion = 16;
  fillSoft(ctx, inner, 5, (dx) =>
    softRectPath(
      ctx,
      pad + cushion + dx,
      pad + cushion,
      width - cushion * 2,
      height - cushion * 2,
      panelRadius * 0.75,
      1,
    ),
  );

  /** Обводка рамки */
  softRectPath(ctx, pad, pad, width, height, panelRadius, bulge);
  strokeSoft(ctx, outline, 3.6);

  /** Светлое окошко под шапкой с обводкой цвета рамки */
  softRectPath(
    ctx,
    pad + panelInset,
    pad + panelHeader,
    width - panelInset * 2,
    height - panelHeader - panelInset,
    cardRadius,
    1,
  );
  ctx.fillStyle = cardColor;
  ctx.fill();
  strokeSoft(ctx, outline, 2.8);
}

/** Дорожка переключателя: включённая — зелёная, как плитка 1024, выключенная — бежевая. */
export function drawToggleTrackTexture(ctx: CanvasRenderingContext2D, isOn: boolean) {
  const { texturePad: pad, toggleWidth, toggleHeight, toggleOff, tones } = nextUiConfig;
  const colors = isOn ? tones.green : toggleOff;

  softRectPath(ctx, pad, pad, toggleWidth, toggleHeight, toggleHeight / 2, 0.8);
  ctx.fillStyle = toRgba(colors.body);
  ctx.fill();
  strokeSoft(ctx, colors.outline, 2.8);
}

/** Ручка переключателя: светлый неровный круг с обводкой кнопок. */
export function drawToggleKnobTexture(ctx: CanvasRenderingContext2D) {
  const { texturePad: pad, toggleKnobSize, cardColor, buttonOutline } = nextUiConfig;
  const center = pad + toggleKnobSize / 2;

  blobPath(ctx, center, center, toggleKnobSize / 2, toggleKnobSize / 2, 2, 0.012, 7);
  ctx.fillStyle = cardColor;
  ctx.fill();
  strokeSoft(ctx, buttonOutline, 2.6);
}

/** Значок строки настроек: цветной круг кнопок игры и линейная иконка, размеры — доли диаметра. */
export function drawRowIconTexture(ctx: CanvasRenderingContext2D, icon: NextUiRowIcon) {
  const {
    texturePad: pad,
    rowIconSize: size,
    buttonOutline,
    buttonColors,
    textColor,
  } = nextUiConfig;
  const center = pad + size / 2;

  blobPath(ctx, center, center, size / 2, size / 2, 2, 0.012, icon.length);
  ctx.fillStyle = toRgba(icon === "speaker" ? buttonColors.undo : buttonColors.restart);
  ctx.fill();
  strokeSoft(ctx, buttonOutline, 2.6);

  /** Иконка рисуется в единичных координатах и масштабируется на диаметр */
  ctx.save();
  ctx.translate(center, center);
  ctx.scale(size, size);
  ctx.lineWidth = 0.062;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = textColor;
  ctx.fillStyle = textColor;

  if (icon === "speaker") {
    ctx.stroke(
      new Path2D(
        "M-0.2 -0.07L-0.1 -0.07L0.03 -0.17L0.03 0.17L-0.1 0.07L-0.2 0.07ZM0.11 -0.09Q0.18 0 0.11 0.09M0.16 -0.17Q0.29 0 0.16 0.17",
      ),
    );
  } else {
    ctx.stroke(new Path2D("M-0.06 0.16L-0.06 -0.14L0.17 -0.2L0.17 0.1M-0.06 -0.03L0.17 -0.09"));
    /** Два нотных кружка */
    for (const [x, y] of [
      [-0.11, 0.15],
      [0.12, 0.1],
    ]) {
      ctx.beginPath();
      ctx.arc(x, y, 0.055, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}
