import { JellyLoops, JellyMesh } from "../../../../common/animation/animation-jelly";
import { addJellyButtonBehavior } from "../../../shared/jelly-button/addJellyButtonBehavior";
import { next2048Config } from "../../config";
import { Next2048Textures, type ButtonIcon } from "../../shared/Next2048Textures/Next2048Textures";

interface IJellyButtonProps {
  scene: Phaser.Scene;
  icon: ButtonIcon;
  onClick: () => void;
}

/**
 * Круглая желейная кнопка: при наведении край оживает, при нажатии она вдавливается,
 * а при отпускании пружинит, как желейная пимпочка.
 * Поведение и его анимации — addJellyButtonBehavior (по умолчанию как раз под круглую кнопку).
 */
export class JellyButton extends Phaser.GameObjects.Container {
  constructor(private props: IJellyButtonProps) {
    super(props.scene, 0, 0);
    const { scene, icon, onClick } = this.props;
    const { buttonSize } = next2048Config;

    /** Зона задаёт размер и область нажатия: у Mesh нет getBounds */
    this.add(new Phaser.GameObjects.Zone(scene, 0, 0, buttonSize, buttonSize));

    const jelly = new JellyMesh({
      scene,
      x: 0,
      y: 0,
      textureKey: Next2048Textures.button(icon),
      width: Next2048Textures.buttonSize,
      height: Next2048Textures.buttonSize,
    });
    this.add(jelly);
    /** Живая рябь кнопки: плавно и спокойно — рябь по умолчанию; кнопка 162 px */
    JellyLoops.loopEdgeRipple({ jelly });

    addJellyButtonBehavior({ obj: this, jelly, clickOn: "press", onClick });
  }
}
