import type { IJellyMotionArgs } from "../types";

/** Настройки вдавливания. */
export interface IPressDownOptions {
  /** сплющивание в глубине нажатия, доля размера; по умолчанию 0.256 */
  squashShare?: number;
  /** раздувание вширь в глубине нажатия, доля размера; по умолчанию 0.07 */
  bulgeShare?: number;
}

/**
 * Вдавливание вдоль оси, по умолчанию за 90 мс: сплющивание и раздувание растут от текущей формы, без скачка,
 * растяжение от езды сходит в тот же tween.
 * Прежние анимации формы обрываются (их onComplete не придёт): вдавливание забирает форму себе.
 */
export function pressDownMotion(args: IJellyMotionArgs & IPressDownOptions): Phaser.Tweens.Tween {
  const { jelly, direction, durationMs = 90, squashShare = 0.256, bulgeShare = 0.07, onComplete } = args;
  if (direction) jelly.setDirection(direction.x, direction.y);

  jelly.stopShape();
  return jelly.animate({ stretch: 0, squash: squashShare, bulge: bulgeShare }, durationMs, "Quad.Out", {
    onComplete,
  });
}
