import {
  JellyLoops,
  JellyMotions,
  type JellyLoopStart,
  type JellyMotion,
} from "../../../common/animation/animation-jelly";
import type { IJellyButtonMotion } from "../jelly-button/jellyButtonMotion";

/**
 * Движение UI нового дизайна: широкие формы (текстовая плитка, дорожка переключателя) и ручка переключателя.
 * Значения по умолчанию JellyMotions и JellyLoops подобраны под круглую кнопку 162 px; на широкой форме та же доля
 * размера даёт втрое больше пикселей, и край ломается. Поэтому тут они мягче; силы — доли размера (*Share).
 * Своё у объекта — замыкание: (args) => JellyMotions.pressDown({ squashShare: 0.1, ...args }).
 */
export const nextUiMotion = {
  /** Текстовая плитка 330×108: наведение, нажатие и отпускание в 2–2,5 раза мягче круглой кнопки */
  wideButton: {
    /** колыхание края: 0.0315 по умолчанию → 0.012 */
    hoverLoop: (args) => JellyLoops.loopEdgeWave({ edgeWaveShare: 0.012, ...args }),
    /** вдавливание: сплющивание 0.256 → 0.128, раздувание 0.07 → 0.035 */
    pressAnimation: (args) =>
      JellyMotions.pressDown({ squashShare: 0.128, bulgeShare: 0.035, ...args }),
    /** пружина как у кнопки, колыхание края в начале слабее: 0.07 → 0.03 */
    releaseAnimation: (args) => JellyMotions.springRelease({ edgeWaveShare: 0.03, ...args }),
  } satisfies IJellyButtonMotion,

  /** Дорожка переключателя 150×72: ещё мягче плитки — она узкая и должна оставаться читаемой дорожкой */
  toggleTrack: {
    hoverLoop: (args) => JellyLoops.loopEdgeWave({ edgeWaveShare: 0.008, ...args }),
    pressAnimation: (args) =>
      JellyMotions.pressDown({ squashShare: 0.09, bulgeShare: 0.025, ...args }),
    releaseAnimation: (args) => JellyMotions.springRelease({ edgeWaveShare: 0.02, ...args }),
  } satisfies IJellyButtonMotion,

  /** Ручка переключателя: едет как капля, но тянется и шлёпается слабее плитки поля */
  toggleKnob: {
    /** езда ручки в другой край, мс */
    moveMs: 130,
    /** растяжение по ходу: 0.22 по умолчанию → 0.12 */
    moveAnimation: ((args) =>
      JellyMotions.stretchAlongMove({ stretchShare: 0.12, ...args })) satisfies JellyMotion,
    /** шлепок у края: сплющивание 0.16 → 0.08 */
    landAnimation: ((args) =>
      JellyMotions.squashAndSpringBack({ squashShare: 0.08, ...args })) satisfies JellyMotion,
  },

  /** Живая рябь широкой формы: плавно, медленно, длинные волны — капсулы счёта, текстовой плитки, дорожки */
  wideIdleLoop: ((args) =>
    JellyLoops.loopEdgeRipple({
      /** край в самый бурный момент отходит от покоя на столько, px */
      edgeOffsetMaxPx: 1.5,
      /** край в самый тихий момент, px */
      edgeOffsetMinPx: 0.5,
      /** один плавный переезд силы к новой случайной цели, мс */
      calmChangeMinMs: 2000,
      calmChangeMaxMs: 5000,
      /** гребней волны по контуру, целое */
      crestCountMin: 2,
      crestCountMax: 4,
      /** гребень обходит контур за столько секунд */
      crestLapMinSec: 20,
      crestLapMaxSec: 60,
      /** узор одной волны рождается и гаснет за столько мс */
      waveLifeMinMs: 2500,
      waveLifeMaxMs: 7000,
      ...args,
    })) satisfies JellyLoopStart,
};
