import { makeAlign, makeView } from "@kvisaz/phaser-common";
import { nextUiConfig } from "../config";
import { NextUiTextures, type NextUiRowIcon } from "../NextUiTextures";
import { NextUiToggle } from "../NextUiToggle/NextUiToggle";

interface INextUiToggleRowProps {
  scene: Phaser.Scene;
  icon: NextUiRowIcon;
  /** подпись настройки: готовая строка */
  label: string;
  /** начальное состояние переключателя */
  on: boolean;
  onChange: (on: boolean) => void;
}

/** Строка настройки: значок слева, подпись, переключатель у правого края. */
export class NextUiToggleRow extends Phaser.GameObjects.Container {
  constructor(private props: INextUiToggleRowProps) {
    super(props.scene, 0, 0);
    const { scene, icon, label, on, onChange } = this.props;
    const { rowWidth, rowIconSize, rowFontSize, rowIconGap, texturePad, fontFamily, textColor } =
      nextUiConfig;

    /** Зона задаёт размер строки для раскладки */
    const zone = new Phaser.GameObjects.Zone(scene, 0, 0, rowWidth, rowIconSize + texturePad * 2);
    this.add(zone);

    const iconImage = makeView(scene, (b) =>
      b.img({ textureName: NextUiTextures.rowIcon(scene, icon) }),
    );
    const labelText = makeView(scene, (b) =>
      b.text({
        text: label,
        style: { fontFamily, fontSize: `${rowFontSize}px`, color: textColor },
      }),
    );
    const toggle = new NextUiToggle({ scene, on, onChange });
    this.add([iconImage, labelText, toggle]);

    makeAlign((align) => {
      align
        .anchor(zone)
        .leftIn(iconImage)
        .centerY(iconImage)
        .rightIn(toggle)
        .centerY(toggle)
        .centerY(labelText);
      align.anchor(iconImage).rightTo(labelText, rowIconGap);
    });
  }
}
