import type { IGameCoreSoundConfig } from "@kvisaz/phaser-common";
import { autoAssetsConfig } from "../autoAssetsConfig";
import type { IGameSoundEvents } from "../services/sound/events";

/** Вариант звука слияния: имя ассета и своя громкость. */
interface IMergeSound {
  name: string;
  volume: number;
}

/** Тир слияния Next 2048: до какого номинала действует и какие варианты играют по кругу. */
interface IMergeSoundTier {
  upTo: number;
  sounds: IMergeSound[];
}

/**
 * Слияния Next 2048: звуки подобраны на слух.
 * Внутри тира варианты идут по кругу — одинаковые слияния звучат по-разному.
 * Громкость у каждого варианта своя: у тихих файлов она выше, чтобы тир звучал ровно.
 */
const next2048MergeTiers: IMergeSoundTier[] = [
  {
    upTo: 8,
    sounds: [
      { name: autoAssetsConfig.sounds.deep16.name, volume: 0.92 },
      { name: autoAssetsConfig.sounds.deep15.name, volume: 1 },
    ],
  },
  {
    upTo: 32,
    sounds: [{ name: autoAssetsConfig.sounds.deep03.name, volume: 0.6 }],
  },
  {
    upTo: 128,
    sounds: [{ name: autoAssetsConfig.sounds.deep18.name, volume: 0.66 }],
  },
  {
    upTo: 512,
    sounds: [
      { name: autoAssetsConfig.sounds.deep19.name, volume: 0.9 },
      { name: autoAssetsConfig.sounds.deep09.name, volume: 1 },
    ],
  },
  {
    upTo: Number.POSITIVE_INFINITY,
    sounds: [{ name: autoAssetsConfig.sounds.deep13.name, volume: 0.6 }],
  },
];

/** Звуки действий Next 2048: перемещение плиток, клик и hover кнопок. */
const next2048ActionSounds = {
  move: { name: autoAssetsConfig.sounds.hoverCardFlip.name, volume: 0.55 },
  click: { name: autoAssetsConfig.sounds.pop2.name, volume: 0.9 },
  hover: { name: autoAssetsConfig.sounds.hoverCardFlip.name, volume: 0.35 },
};

/** Номер следующего варианта в каждом тире слияния: счётчик живёт вместе с конфигом. */
const nextMergeSoundIndexes = new Map<number, number>();

/**
 * Настройки звука, как их выбрал игрок: один общий объект на диалог настроек и GameSoundService,
 * живёт всю игру. Диалог меняет его и шлёт coreSoundSettingsChanged, сервис сохраняет выбор (PlayerDataService)
 * и при следующем запуске восстанавливает его в этот же объект. По умолчанию музыка и эффекты включены.
 */
export const soundSettings = { isMusicOn: true, isSoundOn: true };

/** Единые звуки игры: настройки и временный mute применяет GameSoundService из ServicesScene. */
export const soundConfig: IGameCoreSoundConfig<IGameSoundEvents> = {
  initialSettings: { ...soundSettings },
  /** Фоновая музыка в цикле: 90 с, −26 LUFS; громкость подобрана на уровне музыки пасьянсов (−14 LUFS при 0.09) */
  music: { soundName: autoAssetsConfig.sounds.next2048Music.name, volume: 0.3 },
  effects: {
    onButtonClick: (scene) =>
      scene.sound.play(next2048ActionSounds.click.name, {
        volume: next2048ActionSounds.click.volume,
      }),
    onButtonHover: (scene) =>
      scene.sound.play(next2048ActionSounds.hover.name, {
        volume: next2048ActionSounds.hover.volume,
      }),
    /** Слияние Next 2048: вариант выбирается по тиру и играет по кругу. */
    next2048MergeSound: (scene, { value }) => {
      const tierIndex = findMergeTierIndex(value);
      const sound = pickNextMergeSound(tierIndex, next2048MergeTiers[tierIndex]);
      scene.sound.play(sound.name, { volume: sound.volume });
    },
    /** Ход, который сдвинул поле: тихий шорох на каждый свайп. */
    next2048MoveSound: (scene) =>
      scene.sound.play(next2048ActionSounds.move.name, {
        volume: next2048ActionSounds.move.volume,
      }),

    /**
     * TODO: звук появления диалога (диалоги ещё не сделаны) — deep_19.
     * TODO: звук победы (победа ещё не сделана) — fanfare.
     * События: next2048DialogSound, next2048VictorySound.
     */
  },
};

/** Индекс тира слияния для номинала: первый тир, чей upTo не меньше значения. */
function findMergeTierIndex(value: number): number {
  const index = next2048MergeTiers.findIndex((tier) => value <= tier.upTo);
  return index === -1 ? next2048MergeTiers.length - 1 : index;
}

/** Следующий по кругу вариант тира: без случайных повторов подряд. */
function pickNextMergeSound(tierIndex: number, tier: IMergeSoundTier): IMergeSound {
  const index = nextMergeSoundIndexes.get(tierIndex) ?? 0;
  nextMergeSoundIndexes.set(tierIndex, (index + 1) % tier.sounds.length);
  return tier.sounds[index];
}
