import { onScenePauseResume } from "@kvisaz/phaser-common";

/**
 * Ждёт отпускания указателя и зовёт callback РОВНО ОДИН РАЗ: при отпускании ИЛИ при паузе сцены.
 * Зачем пауза: когда поверх сцены открывается диалог, сцена встаёт на паузу и больше не получает input,
 * так что отпускание не придёт никогда — кнопка осталась бы вдавленной, а подписка висела до чужого клика.
 * Пружина, запущенная при паузе, замирает вместе со сценой и доигрывает, когда диалог закроется.
 * Ждать отпускания в компонентах — только через эту функцию, scene.input.once(POINTER_UP) там не нужен.
 */
export function onPointerReleased(scene: Phaser.Scene, callback: () => void): void {
  const stopPauseWatch = onScenePauseResume({
    scene,
    onSwitch: (paused) => {
      if (paused) done();
    },
  });

  /** Снимает обе подписки и зовёт callback; второй вызов невозможен — подписок уже нет */
  function done() {
    scene.input.off(Phaser.Input.Events.POINTER_UP, done);
    stopPauseWatch();
    callback();
  }

  scene.input.once(Phaser.Input.Events.POINTER_UP, done);
}
