import { next2048Config } from "../../config";
import {
  canvasFont,
  fillSoft,
  softRectPath,
  strokeSoft,
  toRgba,
} from "../../../../common/canvas/canvas";

/** Прозрачная кайма вокруг плитки, px: выпуклые стороны и мягкая обводка не режутся краем текстуры. */
const tilePad = 6;

/** Сторона текстуры плитки = размер её Mesh. */
export const tileTextureSize = next2048Config.cellSize + tilePad * 2;

/** Высота среза линии рамки = толщина Rope. */
export const lineTextureHeight = next2048Config.lineThickness + 2;

/**
 * Плитка как на макете: тело цвета номинала, внутри «подушка» с мягким краем,
 * обводка тоном темнее, цифра шрифтом Nunito.
 */
export function drawTileTexture(ctx: CanvasRenderingContext2D, value: number) {
  const { cellSize, tileRadius, textColor, fontFamily } = next2048Config;
  const size = tileTextureSize;
  const { body, inner, outline } = getTileColors(value);
  const bulge = 1.5;

  /** Тело */
  softRectPath(ctx, tilePad, tilePad, cellSize, cellSize, tileRadius, bulge);
  ctx.fillStyle = toRgba(body);
  ctx.fill();

  /** «Подушка»: внутренний квадрат темнее с размытым краем, как акварельный мазок */
  const inset = cellSize * 0.11;
  const innerSize = cellSize - inset * 2;
  fillSoft(ctx, inner, 4, (dx) =>
    softRectPath(
      ctx,
      tilePad + inset + dx,
      tilePad + inset,
      innerSize,
      innerSize,
      tileRadius * 0.85,
      bulge * 0.6,
    ),
  );

  /** Обводка поверх тела */
  softRectPath(ctx, tilePad, tilePad, cellSize, cellSize, tileRadius, bulge);
  strokeSoft(ctx, outline, 3);

  /** Цифра: чем длиннее число, тем мельче шрифт; доли сняты с макета */
  const digits = String(value).length;
  const fontRatio = digits <= 2 ? 0.53 : digits === 3 ? 0.45 : digits === 4 ? 0.33 : 0.27;
  ctx.font = canvasFont(cellSize * fontRatio, fontFamily);
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = textColor;
  ctx.fillText(String(value), size / 2, size / 2 + cellSize * 0.02);
}

/** Пустая клетка: тонкий пунктирный скруглённый квадрат. */
export function drawSlotTexture(ctx: CanvasRenderingContext2D) {
  const { cellSize, tileRadius, slotLineColor } = next2048Config;

  softRectPath(ctx, 2, 2, cellSize - 4, cellSize - 4, tileRadius * 0.8, 0);
  ctx.setLineDash([10, 8]);
  ctx.lineWidth = 2.3;
  ctx.strokeStyle = slotLineColor;
  ctx.stroke();
}

/** Срез линии для Rope: высота текстуры — толщина линии, края по высоте мягкие. */
export function drawLineTexture(ctx: CanvasRenderingContext2D) {
  const { lineColor } = next2048Config;
  const height = lineTextureHeight;

  const gradient = ctx.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, toRgba(lineColor, 0));
  gradient.addColorStop(0.2, toRgba(lineColor, 1));
  gradient.addColorStop(0.8, toRgba(lineColor, 1));
  gradient.addColorStop(1, toRgba(lineColor, 0));
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 8, height);
}

/** Цвета плитки по номиналу; большие номиналы берут цвета по кругу. */
export function getTileColors(value: number) {
  const { tileColors, tileColorsHigh } = next2048Config;
  return tileColors[value] ?? tileColorsHigh[Math.round(Math.log2(value)) % tileColorsHigh.length];
}
