import type { IJellyMotionArgs } from "../types";

/** Настройки роста из точки. */
export interface IGrowFromPointOptions {
  /** доля времени, за которую объект вырастает из точки с перехлёстом; по умолчанию 0.55 */
  growTimeShare?: number;
  /** дрожь края в начале, доля радиуса; по умолчанию 0.07 */
  edgeWaveShare?: number;
  /** на сколько радиан пробегают волны края, пока дрожь затихает; по умолчанию 9 */
  edgeWavePhase?: number;
}

/** Рост из точки: объект вырастает с перехлёстом, край дрожит и затихает. Вся анимация по умолчанию — 650 мс. */
export function growFromPointMotion(args: IJellyMotionArgs & IGrowFromPointOptions): Phaser.Tweens.Tween {
  const {
    jelly,
    durationMs = 650,
    growTimeShare = 0.55,
    edgeWaveShare = 0.07,
    edgeWavePhase = 9,
    onComplete,
  } = args;

  jelly.setShape({ grow: 0, wobble: edgeWaveShare });
  jelly.animate({ grow: 1 }, durationMs * growTimeShare, "Back.Out");
  return jelly.animate(
    { wobble: 0, phase: jelly.shape.phase + edgeWavePhase },
    durationMs,
    "Sine.Out",
    { onComplete },
  );
}
