import { generateRuntimeTextures } from "@kvisaz/phaser-common";
import { nextUiConfig } from "./config";
import {
  drawPanelTexture,
  drawRowIconTexture,
  drawTileButtonTexture,
  drawToggleKnobTexture,
  drawToggleTrackTexture,
  type IPanelOptions,
  type ITileButtonOptions,
  type NextUiRowIcon,
} from "./drawNextUiTextures";

export type { NextUiRowIcon };

/** Готовая текстура для Mesh: ключ и размер вместе с каймой = размер Mesh. */
interface INextUiMeshTexture {
  key: string;
  width: number;
  height: number;
}

/**
 * Текстуры UI нового дизайна. Рисуются лениво, при первом запросе, и один раз на ключ:
 * диалоги открываются редко, поэтому на старте игры их рисовать незачем.
 * Подписи на текстуры не рисуются — это отдельный Text, чтобы работала локализация.
 */
export class NextUiTextures {
  /** Кнопка-плитка тона и размера: нужен размер текстуры, потому что на ней строится Mesh. */
  static tileButton(scene: Phaser.Scene, options: ITileButtonOptions): INextUiMeshTexture {
    const { tone, width, height } = options;
    const { texturePad } = nextUiConfig;
    const textureWidth = width + texturePad * 2;
    const textureHeight = height + texturePad * 2;
    const key = ensureTexture(
      scene,
      `nextui_tile_button_${tone}_${width}x${height}`,
      textureWidth,
      textureHeight,
      (ctx) => drawTileButtonTexture(ctx, options),
    );

    return { key, width: textureWidth, height: textureHeight };
  }

  /** Панель диалога акцента и размера: цветная рамка и светлое окошко. Возвращает ключ текстуры. */
  static panel(scene: Phaser.Scene, options: IPanelOptions): string {
    const { accent, width, height } = options;
    const { texturePad } = nextUiConfig;

    return ensureTexture(
      scene,
      `nextui_panel_${accent}_${width}x${height}`,
      width + texturePad * 2,
      height + texturePad * 2,
      (ctx) => drawPanelTexture(ctx, options),
    );
  }

  /** Дорожка переключателя во включённом или выключенном виде. Возвращает ключ текстуры. */
  static toggleTrack(scene: Phaser.Scene, isOn: boolean): string {
    const { texturePad, toggleWidth, toggleHeight } = nextUiConfig;

    return ensureTexture(
      scene,
      `nextui_toggle_track_${isOn ? "on" : "off"}`,
      toggleWidth + texturePad * 2,
      toggleHeight + texturePad * 2,
      (ctx) => drawToggleTrackTexture(ctx, isOn),
    );
  }

  /** Ручка переключателя. Возвращает ключ текстуры. */
  static toggleKnob(scene: Phaser.Scene): string {
    const { texturePad, toggleKnobSize } = nextUiConfig;
    const size = toggleKnobSize + texturePad * 2;

    return ensureTexture(scene, "nextui_toggle_knob", size, size, drawToggleKnobTexture);
  }

  /** Значок строки настроек. Возвращает ключ текстуры. */
  static rowIcon(scene: Phaser.Scene, icon: NextUiRowIcon): string {
    const { texturePad, rowIconSize } = nextUiConfig;
    const size = rowIconSize + texturePad * 2;

    return ensureTexture(scene, `nextui_row_icon_${icon}`, size, size, (ctx) =>
      drawRowIconTexture(ctx, icon),
    );
  }
}

/** Рисует текстуру при первом запросе ключа; повторный вызов ничего не рисует. Возвращает ключ. */
function ensureTexture(
  scene: Phaser.Scene,
  key: string,
  width: number,
  height: number,
  draw: (ctx: CanvasRenderingContext2D) => void,
): string {
  generateRuntimeTextures({
    scene,
    textures: [{ textureName: key, width, height, generatorFn: ({ context }) => draw(context) }],
  });

  return key;
}
