import { SafeEventsAdapter, SceneEvents } from "@kvisaz/phaser-common";
import { connectLinks, link } from "../../../common/events/connectEvents";
import type { IGameEvents } from "../../../events";
import { services } from "../../../services";
import type { INextUiButtonEvents } from "./events";

/**
 * Мост звука кнопок: клик и наведение из событий сцены → общая шина, где их слушает SoundFeature.
 * makeButton шлёт события в сцену, где лежит кнопка, поэтому мост нужен каждой сцене с кнопками:
 * игровой и каждой modal-сцене диалога. Отписку снимет connectLinks при выключении сцены.
 */
export function connectUiSounds(scene: Phaser.Scene) {
  const soundEvents = new SafeEventsAdapter<IGameEvents>(services.gameEvents);
  const buttonEvents = new SceneEvents<INextUiButtonEvents>({ scene });

  return connectLinks({
    scene,
    links: [
      link(buttonEvents, "onButtonClick", soundEvents, "onButtonClick"),
      link(buttonEvents, "onButtonHover", soundEvents, "onButtonHover"),
    ],
  });
}
