import {
  makeAlign,
  makeView,
  onValueData,
  setValueData,
  UnSubManager,
} from "@kvisaz/phaser-common";
import { JellyMesh } from "../../../../common/animation/animation-jelly";
import { nextUiMotion } from "../../../shared/next-ui/nextUiMotion";
import { next2048Config } from "../../config";
import { Next2048Textures } from "../../shared/Next2048Textures/Next2048Textures";
import { scoreBlockMotion } from "./scoreBlockMotion";

interface IScoreBlockProps {
  scene: Phaser.Scene;
  /** подпись над капсулой: готовая строка */
  label: string;
  /** ключ текстуры своей капсулы из Next2048Textures: у счёта и рекорда разные цвета */
  textureKey: string;
}

/**
 * Подпись разрядкой и желейная капсула с числом; при росте числа капсула «хлюпает».
 * Обновлять — через setValueData(block, число), как общий инфоблок phaser-common.
 */
export class ScoreBlock extends Phaser.GameObjects.Container {
  private readonly unSubs = new UnSubManager();
  private readonly pill: JellyMesh;
  /** Меняющееся состояние: показанное число — чтобы понять, вырос ли счёт */
  private readonly gameState = { value: 0 };

  constructor(private props: IScoreBlockProps) {
    super(props.scene, 0, 0);
    const { scene, label, textureKey } = this.props;
    const {
      pillWidth,
      pillHeight,
      pillFontSize,
      labelFontSize,
      labelLetterSpacing,
      labelColor,
      labelGap,
      textColor,
      fontFamily,
    } = next2048Config;

    /** Зона задаёт размер капсулы для раскладки: у Mesh нет getBounds */
    const pillZone = new Phaser.GameObjects.Zone(scene, 0, 0, pillWidth, pillHeight);
    this.add(pillZone);

    this.pill = new JellyMesh({
      scene,
      x: 0,
      y: 0,
      textureKey,
      width: Next2048Textures.pillWidth,
      height: Next2048Textures.pillHeight,
    });
    this.add(this.pill);
    nextUiMotion.wideIdleLoop({ jelly: this.pill });

    const labelText = makeView(scene, (b) =>
      b.text({
        text: label,
        style: { fontFamily, fontSize: `${labelFontSize}px`, color: labelColor },
      }),
    ).setLetterSpacing(labelLetterSpacing);
    this.add(labelText);

    const valueText = makeView(scene, (b) =>
      b.text({
        text: "0",
        style: { fontFamily, fontSize: `${pillFontSize}px`, color: textColor },
      }),
    ).setOrigin(0.5);
    this.add(valueText);

    makeAlign((align) => {
      align.anchor(pillZone).centerX(labelText).topTo(labelText, -labelGap);
      align.anchor(pillZone).center(valueText);
    });

    /** Обязательно ставим value прежде чем слушать */
    setValueData(this, 0);
    this.unSubs.addUnSub(
      onValueData<number>(this, (value) => {
        /** Раскладка — только в покое: прыжок меняет границы текста */
        scene.tweens.killTweensOf(valueText);
        valueText.setScale(1);
        valueText.setText(String(value));
        makeAlign((align) => align.anchor(pillZone).center(valueText));
        this.pulse(value, valueText);
      }),
    );
    this.unSubs.addUnSub(() => scene.tweens.killTweensOf(valueText));
  }

  /** Снимает подписку на value; дети уничтожаются вместе с контейнером. */
  destroy(fromScene?: boolean) {
    this.unSubs.destroy();
    super.destroy(fromScene);
  }

  /** При росте числа капсула коротко раздувается и колышется, а число подпрыгивает и пружинит обратно. */
  private pulse(value: number, valueText: Phaser.GameObjects.Text) {
    const { gameState, pill } = this;
    const { scene } = this.props;
    const grew = value > gameState.value;
    gameState.value = value;
    if (!grew) return;

    scoreBlockMotion.scoreGrowAnimation({ jelly: pill });

    /** Масштаб от центра текста (origin 0.5): центровка на капсуле не сбивается */
    const { valueBounceScale, valueBounceUpMs, valueBounceBackMs } = scoreBlockMotion;
    scene.tweens.chain({
      targets: valueText,
      tweens: [
        { scale: valueBounceScale, duration: valueBounceUpMs, ease: "Quad.Out" },
        { scale: 1, duration: valueBounceBackMs, ease: "Elastic.Out", easeParams: [1.1, 0.4] },
      ],
    });
  }
}
