import { SafeEventsAdapter } from "@kvisaz/phaser-common";
import { soundSettings } from "../../../configs/config.sound";
import { services } from "../../../services";
import { getLocalizedText } from "../../../services/locale";
import type { IGameSoundEvents } from "../../../services/sound/events";
import { openNextDialog } from "../../shared/next-ui/openNextDialog/openNextDialog";

interface INext2048DialogsProps {
  /** сцена игры: она встаёт на паузу, пока диалог открыт */
  scene: Phaser.Scene;
}

/**
 * Диалоги экрана Next 2048: подтверждение новой игры и настройки. Только логика и тексты,
 * вид диалогов — в shared/next-ui (openNextDialog). Методы ничего не возвращают: результат — колбэк.
 *
 * TODO: кнопка «меню» откроет полноценное меню с выходом на старт и в настройки;
 * пока она открывает сразу настройки.
 */
export class Next2048Dialogs {
  private readonly soundEvents = new SafeEventsAdapter<IGameSoundEvents>(services.gameEvents);

  constructor(private props: INext2048DialogsProps) {}

  /** Спрашивает «Вы уверены?» перед новой игрой; onConfirm — после закрытия диалога, если игрок согласился. */
  confirmNewGame(onConfirm: () => void) {
    const { scene } = this.props;

    void openNextDialog({
      parentScene: scene,
      spec: {
        accent: "peach",
        title: getLocalizedText("next2048RestartTitle"),
        message: getLocalizedText("next2048RestartMessage"),
        actions: [
          { id: "yes", label: getLocalizedText("yes"), tone: "green" },
          { id: "no", label: getLocalizedText("no"), tone: "pink" },
        ],
      },
    }).then((answer) => {
      if (answer === "yes") onConfirm();
    });
  }

  /** Открывает настройки: каждый переключатель применяется сразу, кнопка «Готово» только закрывает диалог. */
  openSettings() {
    const { scene } = this.props;

    void openNextDialog({
      parentScene: scene,
      spec: {
        accent: "blue",
        title: getLocalizedText("next2048SettingsTitle"),
        toggles: [
          {
            icon: "speaker",
            label: getLocalizedText("next2048SettingsSound"),
            on: soundSettings.isSoundOn,
            onChange: (on) => this.changeSoundSettings({ isSoundOn: on }),
          },
          {
            icon: "note",
            label: getLocalizedText("next2048SettingsMusic"),
            on: soundSettings.isMusicOn,
            onChange: (on) => this.changeSoundSettings({ isMusicOn: on }),
          },
        ],
        actions: [{ id: "done", label: getLocalizedText("next2048SettingsDone"), tone: "green" }],
      },
    });
  }

  /** Сообщает звуковой системе выбор игрока: GameSoundService запомнит его в soundSettings и сохранит, SoundFeature применит сразу. */
  private changeSoundSettings(patch: Partial<typeof soundSettings>) {
    this.soundEvents.emit("coreSoundSettingsChanged", { ...soundSettings, ...patch });
  }
}
