import type { IJellyOutlineMotionArgs } from "../types";

/** Настройки волны удара. */
export interface IImpactRippleOptions {
  /** высота волны в начале, px; по умолчанию 14 */
  heightPx?: number;
  /** ширина волны в начале, в точках контура; растёт со временем; по умолчанию 22 */
  spreadPoints?: number;
}

/**
 * Волна удара: от ближайшей к точке (x, y) части контура в обе стороны бежит затухающая рябь;
 * по умолчанию бежит и гаснет за 1100 мс. Возвращает её tween; по концу волна убирается с контура.
 */
export function impactRippleMotion(args: IJellyOutlineMotionArgs & IImpactRippleOptions): Phaser.Tweens.Tween {
  const { outline, x, y, durationMs = 1100, heightPx = 14, spreadPoints = 22, onComplete } = args;
  const index = outline.nearestPointIndex(x, y);

  /** Мутируется tween-ом: t от 0 до 1 — время жизни волны */
  const wave = {
    t: 0,
    sample: () => {},
    offsetPx: (pointIndex: number, pointCount: number) => {
      const { t } = wave;
      /** расстояние по петле в точках: волна бежит в обе стороны; «мягкий модуль» убирает излом в точке удара */
      const raw = Math.abs(pointIndex - index);
      const loopD = Math.min(raw, pointCount - raw);
      const d = Math.sqrt(loopD * loopD + 9);
      /** огибающая расползается со временем и гаснет к концу */
      const spread = spreadPoints * (0.4 + t * 2.5);
      const fade = (1 - t) * (1 - t);
      /** гауссова огибающая: гладкий горб без острого пика */
      return heightPx * fade * Math.exp(-((d / spread) ** 2)) * Math.cos(d * 0.35 - t * 22);
    },
  };
  outline.addWave(wave);

  return outline.scene.tweens.add({
    targets: wave,
    t: 1,
    duration: durationMs,
    ease: "Linear",
    onComplete: () => {
      outline.removeWave(wave);
      onComplete?.();
    },
  });
}
