import { makeButton, onScenePauseResume } from "@kvisaz/phaser-common";
import type { IJellyLoop, JellyMesh } from "../../../common/animation/animation-jelly";
import { jellyButtonMotion, type IJellyButtonMotion } from "./jellyButtonMotion";
import { onPointerReleased } from "./onPointerReleased";

interface IAddJellyButtonBehaviorProps {
  /** контейнер кнопки: ему даётся интерактивность и события наведения и нажатия */
  obj: Phaser.GameObjects.Container;
  /** желе кнопки, которое вдавливается и колышется */
  jelly: JellyMesh;
  /** свои анимации поверх jellyButtonMotion: нужны кнопке другой формы, чем круглая; без них — по умолчанию */
  motion?: Partial<IJellyButtonMotion>;
  /** когда срабатывает onClick: на нажатие или на отпускание над кнопкой (ушёл с кнопки — нажатие отменено) */
  clickOn: "press" | "release";
  onClick: () => void;
  /** кнопка вдавлена: доп. реакция, например сдвиг подписи */
  onPress?: () => void;
  /** кнопка отпущена: вернуть то, что сделал onPress */
  onRelease?: () => void;
  /** кнопку включили или выключили: например, показать её тусклой */
  onEnabledChange?: (enabled: boolean) => void;
}

/** Меняющееся состояние поведения: наведение, нажатие и бесконечное колыхание наведения. */
interface IJellyButtonBehaviorState {
  /** указатель над кнопкой: после отпускания колыхание наведения возвращается */
  hovered: boolean;
  /** нажали на кнопке и не уходили с неё: только тогда отпускание — это клик (clickOn: "release") */
  pressed: boolean;
  /** колыхание наведения; после нажатия его tween-ы оборваны, но stop() при уходе всё равно гасит колыхание */
  hoverLoop?: IJellyLoop;
}

/**
 * Поведение желейной кнопки: при наведении край оживает, при нажатии она вдавливается,
 * а при отпускании пружинит, как желейная пимпочка. Общее для JellyButton и NextUiButton.
 * Анимации — слоты jellyButtonMotion (JellyMotions и JellyLoops), поверх них — props.motion;
 * функция решает только, когда и какую играть.
 */
export function addJellyButtonBehavior(props: IAddJellyButtonBehaviorProps): void {
  const { obj, jelly, clickOn, onClick, onPress, onRelease, onEnabledChange } = props;
  const { scene } = obj;
  const motion = { ...jellyButtonMotion, ...props.motion };
  const state: IJellyButtonBehaviorState = { hovered: false, pressed: false };

  /** makeButton зовёт onClick на нажатие: на отпускание действие отдаём в POINTER_UP объекта */
  makeButton({
    obj,
    onClick: () => {
      press();
      if (clickOn === "press") onClick();
    },
    onHover: () => {
      state.hovered = true;
      hover();
    },
    onOut: () => {
      state.hovered = false;
      state.pressed = false;
      unhover();
    },
    onEnabledChange: (_, enabled) => {
      if (!enabled) state.pressed = false;
      onEnabledChange?.(enabled);
    },
  });

  if (clickOn === "release") {
    obj.on(Phaser.Input.Events.GAMEOBJECT_POINTER_UP, () => {
      if (!state.pressed) return;
      state.pressed = false;
      onClick();
    });
  }

  /**
   * Диалог поверх ставит сцену на паузу, и она не получает ни отпускания, ни ухода указателя.
   * Отпускание закрывает onPointerReleased; здесь сбрасывается наведение, чтобы кнопка не застряла в нём.
   */
  const stopPauseWatch = onScenePauseResume({
    scene,
    onSwitch: (paused) => {
      if (!paused) return;
      state.hovered = false;
      state.pressed = false;
      unhover();
    },
  });
  obj.once(Phaser.GameObjects.Events.DESTROY, stopPauseWatch);

  /**
   * Наведение: край начинает медленно колыхаться; loop хранится, чтобы погасить его при уходе.
   * Прежний loop здесь не гасится: после отпускания он уже оборван нажатием, а его stop() добавил бы
   * лишнее затухание поверх нового нарастания. Двойной onHover без onOut маловероятен — тогда второй бег волн
   * остался бы до конца своего runMs.
   */
  function hover() {
    state.hoverLoop = motion.hoverLoop({ jelly });
  }

  /** Уход указателя: колыхание гаснет. */
  function unhover() {
    state.hoverLoop?.stop();
    state.hoverLoop = undefined;
  }

  /** Нажатие: кнопка быстро вдавливается сверху и раздаётся вширь; отпускание — при любом отпускании указателя или паузе сцены. */
  function press() {
    state.pressed = true;

    /** Вдавливание сверху вниз: направление на экране, y вниз */
    motion.pressAnimation({ jelly, direction: { x: 0, y: 1 } });
    onPress?.();

    onPointerReleased(scene, release);
  }

  /** Отпускание: пружинит с перехлёстом вверх и долго колышется. */
  function release() {
    if (!jelly.active) return;

    /** Снимает вдавливание и колыхание наведения: их конец больше не нужен, отпускание забирает форму себе */
    jelly.stopShape();
    motion.releaseAnimation({
      jelly,
      onComplete: () => {
        if (state.hovered && jelly.active) hover();
      },
    });
    onRelease?.();
  }
}
